function assuranceDefaults(){return [{"title": "Soğuk zincir teslimat", "text": "Ürünler, tazeliğini korumaya yardımcı ısı yalıtımlı ambalajlarla gönderilir.", "verified": true}, {"title": "%100 güvenli alışveriş", "text": "Kart bilgileriniz mağazamızda saklanmaz. Ödeme, ödeme sağlayıcısının güvenli formunda tamamlanır.", "verified": true}, {"title": "Katkısız, koruyucusuz", "text": "Ürünlerin içerik, alerjen ve saklama bilgilerini ürün detaylarından inceleyebilirsiniz.", "verified": true}]}
const $=s=>document.querySelector(s), $$=s=>[...document.querySelectorAll(s)];
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const safeRead=(k,f)=>{try{return JSON.parse(localStorage.getItem(k))??f}catch{return f}};
let galleryTouch=null,heroSlideTimer=null,currentRegularOffer=null,regularOfferRequest=0;
const defaults=structuredClone(MAYA_DEFAULTS);let config=structuredClone(defaults);config.shipping={...defaults.shipping,...config.shipping};
let cart=safeRead('maya-cart',[]).filter(x=>MAYA_CATALOG.some(p=>p.id===x.id)&&(MAYA_CATALOG.find(p=>p.id===x.id)?.weights||[500,1000]).map(Number).includes(Number(x.weight))&&Number.isInteger(x.qty)&&x.qty>0&&x.qty<=99);
let selectedWeight=500, quantity=1,checkoutStep=1,summaryExpanded=false,previousFocus=null;let checkoutAddress={},checkoutQuote=null,couponCode='';
const icons={search:'<circle cx="10" cy="10" r="6.5"/><path d="m15 15 6 6"/>',bag:'<path d="M5 7h14l1 14H4L5 7Z"/><path d="M8 8V5a4 4 0 0 1 8 0v3"/>',user:'<circle cx="12" cy="7" r="4"/><path d="M3 22v-2a9 9 0 0 1 18 0v2"/>',menu:'<path d="M3 6h18M3 12h18M3 18h18"/>'};
const icon=k=>`<svg viewBox="0 0 24 24" aria-hidden="true">${icons[k]}</svg>`;
const money=n=>new Intl.NumberFormat('tr-TR',{style:'currency',currency:'TRY',maximumFractionDigits:2}).format(n);
const product=id=>MAYA_CATALOG.find(p=>p.id===id);
const variant=(p,w)=>p.variants?.find(v=>Number(v.weight)===Number(w));
const price=(p,w=500)=>Number(variant(p,w)?.price??p.price*w/500);
const stockFor=(p,w)=>Number(variant(p,w)?.stock??p.stock??0);
const oldPrice=(p,w=500)=>{const v=variant(p,w);return v?(Number(v.compareAt)>Number(v.price)?Number(v.compareAt):null):(Number(p.compareAt)>p.price?Number(p.compareAt)*w/500:null)};
const priceMarkup=(p,w=500)=>`<span class="previous-price ${oldPrice(p,w)?'':'empty-price'}">${oldPrice(p,w)?`<del>${money(oldPrice(p,w))}</del>`:'&nbsp;'}</span><span>${money(price(p,w))}</span>`;
const image=(p,cls='')=>{const main=cls==='product-main-image';return mediaImage(p.image,p.name,main?{className:cls,eager:true,width:960}:{className:cls,width:640,widths:[320,480,640,960],sizes:'(max-width: 760px) 50vw, 25vw'})};
const imageSmall=p=>mediaImage(p.image,p.name,{width:480,widths:[320,480,640],sizes:'120px'});
function storeUrl(routeString='anasayfa'){let [route,id]=routeString.split('/');if(route==='urun'&&id){const p=product(id);if(p)id=p.slug||productUrlSlug(p.name)}if(route==='paket'&&id){const b=findPackage(id);if(b)id=b.slug||b.id}const map=window.MAYA_SERVER?.routePaths||{},base=window.MAYA_SERVER?.basePath||'';return base+'/'+(map[route]??(route==='anasayfa'?'':route))+(id&&id!=='all'?'/'+encodeURIComponent(id):'')}
const a=(hash,text,cls='')=>{if(hash==='giris'&&window.MAYA_SERVER?.customer)hash='hesabim';return `<a class="${cls}" href="${esc(storeUrl(hash))}">${text}</a>`};
const currentRoute=()=>location.hash.startsWith('#teklif=')?'duzenli-siparis':location.hash.slice(1)||window.MAYA_SERVER?.route||'anasayfa';
const count=()=>cart.reduce((s,x)=>s+x.qty,0);
const subtotal=()=>cart.reduce((s,x)=>s+price(product(x.id),x.weight)*x.qty,0);
const shipFee=()=>subtotal()>=config.freeShipping?0:Number(config.shippingFee);
function applyTheme(){const r=document.documentElement;r.style.setProperty('--brand-logo-width',Math.max(80,Math.min(260,Number(config.branding?.logoWidth)||138))+'px');r.style.setProperty('--brand-logo-mobile-width',Math.max(70,Math.min(180,Number(config.branding?.mobileLogoWidth)||118))+'px');for(const [k,v] of Object.entries({green:config.primary,gold:config.accent,cream:config.background})){if(/^#[0-9a-f]{6}$/i.test(v))r.style.setProperty('--'+k,v)}r.style.setProperty('--serif',({modern:'Arial, sans-serif',lora:'MayaLora, Georgia, serif',manrope:'MayaManrope, Arial, sans-serif',inter:'MayaInter, Arial, sans-serif',cormorant:'MayaCormorant, Georgia, serif'}[config.font]||"Georgia, 'Times New Roman', serif"))}
function saveCart(){if(!cart.length)try{sessionStorage.removeItem('maya-regular-checkout');sessionStorage.removeItem('maya-regular-offer')}catch{}checkoutQuote=null;localStorage.setItem('maya-cart',JSON.stringify(cart));$$('[data-count]').forEach(x=>x.textContent=count())}
function add(id,w=500,qty=1){const p=product(id);if(!p)return;if(stockFor(p,w)<=0){toast('Bu ürün şu anda stokta değil.');return}if(cart.filter(x=>x.id===id&&(!p.variants?.length||x.weight===w)).reduce((n,x)=>n+x.qty,0)+qty>stockFor(p,w)){toast('Stok miktarını aşıyorsunuz.');return}const found=cart.find(x=>x.id===p.id&&x.weight===w&&!x.packageId);if(found)found.qty=Math.min(99,found.qty+qty);else cart.push({id:p.id,weight:w,qty:Math.min(99,qty)});saveCart();cartDrawer()}
let toastTimer;function toast(text){$('#toast').textContent=text;$('#toast').classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('visible'),3300)}
function header(){return `<div class="announcement">${esc(config.announcement||'MAYA İLE SOFRANIZA LEZZET KATIN')}</div><header class="header"><div class="head-inner"><button class="icon-btn burger" data-menu aria-label="Menüyü aç">${icon('menu')}</button>${a('anasayfa',storeLogoMarkup(),'logo')}<nav class="nav" aria-label="Ana menü">${a('peynirler',esc(navigationLabel('peynirler','Peynirler')))}${a('seckiler',esc(navigationLabel('seckiler','Kahvaltı Seçkileri')))}${a('hikayemiz',esc(navigationLabel('hikayemiz','Maya’nın Hikâyesi')))}${a('rehber',esc(navigationLabel('rehber','Peynir Rehberi')))}${a('kurumsal',esc(navigationLabel('kurumsal','Kurumsal')))}</nav><div class="head-actions"><button class="icon-btn" data-search aria-label="Ürün ara">${icon('search')}<span class="word">Ara</span></button>${a('giris',icon('user')+'<span class="word">Hesabım</span>','icon-btn account-icon')}<a class="icon-btn" href="${esc(storeUrl('sepet'))}" aria-label="Sepet">${icon('bag')}<span class="count" data-count>${count()}</span></a></div></div></header>`}
function footer(){return `<footer class="footer container"><div class="footer-grid"><div>${a('anasayfa',storeLogoMarkup(true),'logo')}<p>Güzel bir kahvaltının, birlikte oturulan bir sofranın eşlikçisi.</p></div><div><h4>Sofranız için</h4>${a('peynirler','Tüm peynirler')}${a('peynirler/beyaz','Beyaz peynirler')}${a('peynirler/kasar','Kaşar peynirleri')}${a('seckiler',esc(navigationLabel('seckiler','Kahvaltı seçkileri')))}</div><div><h4>Maya’yı tanıyın</h4>${a('hikayemiz',esc(navigationLabel('hikayemiz','Hikâyemiz')))}${a('kurumsal',esc(navigationLabel('kurumsal','Kurumsal')))}${a('rehber',esc(navigationLabel('rehber','Peynir Rehberi')))}${a('iletisim','İletişim')}</div><div><h4>Yanınızdayız</h4>${a('teslimat','Teslimat ve paketleme')}${a('takip','Sipariş takibi')}${a('sss','Sık sorulan sorular')}${a('politikalar','Gizlilik ve satış bilgileri')}<a href="#" data-consent>Çerez tercihleri</a></div></div><div class="footer-bottom"><span>© ${new Date().getFullYear()} Maya Peynir</span><span>Sofranıza lezzet katan bir tanışıklık.</span></div></footer>`}
function card(p){const w=p.weights?.[0]||500;return `<article class="product-card">${a('urun/'+p.id,`<div class="product-image">${image(p)}<span class="product-labels"><span class="overline">MAYA SEÇKİSİ</span>${oldPrice(p,w)?'<span class="discount-badge">İNDİRİM</span>':''}</span></div>`)}<div class="product-info"><h3>${a('urun/'+p.id,esc(p.name))}</h3><p class="product-sub">${esc(p.tag)} · ${w} g</p><div class="product-buy"><div class="price">${priceMarkup(p,w)}<small>${w} g için</small></div><button class="add" data-add="${p.id}" data-add-weight="${w}" ${stockFor(p,w)<=0?'disabled':''} aria-label="${esc(p.name)} sepete ekle"><span class="add-word">${stockFor(p,w)>0?'Sepete ekle':'Stokta yok'}</span><span>+</span></button></div></div></article>`}
function productRow(list,label){return `<div class="product-row" data-product-row><div class="product-row-controls"><button type="button" data-row-prev aria-label="Önceki ürünler">←</button><button type="button" data-row-next aria-label="Sonraki ürünler">→</button></div><div class="product-row-track" tabindex="0" role="region" aria-label="${esc(label)}">${list.map(card).join('')}</div></div>`}
function homeProductRows(){
 const groups=Array.isArray(config.homeGroups)?config.homeGroups:[{title:'Kahvaltınız için seçtiklerimiz.',eyebrow:'MAYA PEYNİR',body:'Damak zevkinize uygun peynirleri keşfedin.',mode:'all',limit:6,button:'Tüm peynirler →',route:'peynirler',enabled:true}];
 return groups.filter(g=>g.enabled!==false).map(g=>{let list=g.mode==='manual'?(g.products||[]).map(product).filter(Boolean):g.mode==='category'?MAYA_CATALOG.filter(p=>p.category===g.category):[...MAYA_CATALOG];list=list.slice(0,Math.max(1,Math.min(30,Number(g.limit)||6)));if(!list.length)return '';const bg=/^#[0-9a-f]{6}$/i.test(g.background||'')?g.background:'';return `<section class="section home-product-surface ${g.fullWidth?'is-full':'container'}" ${bg?`style="--section-bg:${esc(bg)}"`:''}><div class="home-surface-inner ${g.fullWidth?'container':''}"><div class="section-head home-products-heading"><div><div class="eyebrow">${esc(g.eyebrow||'')}</div><h2>${esc(g.title||'Peynirlerimiz')}</h2></div><p>${esc(g.body||'')}</p>${g.button?a(g.route||'peynirler',esc(g.button),'text-link'):''}</div>${productRow(list,g.title||'Peynirlerimiz')}</div></section>`}).join('')
}
function setupProductRows(){$$('[data-product-row]').forEach(root=>{const track=root.querySelector('.product-row-track'),prev=root.querySelector('[data-row-prev]'),next=root.querySelector('[data-row-next]'),controls=root.querySelector('.product-row-controls');if(!track||!prev||!next)return;const update=()=>{prev.disabled=track.scrollLeft<2;next.disabled=track.scrollLeft>=track.scrollWidth-track.clientWidth-2;controls.hidden=track.scrollWidth<=track.clientWidth+2};const step=()=>{const c=track.querySelector('.product-card');return c?c.getBoundingClientRect().width+22:300};prev.onclick=()=>track.scrollBy({left:-step()*2,behavior:'smooth'});next.onclick=()=>track.scrollBy({left:step()*2,behavior:'smooth'});enableProductDrag(track);track.addEventListener('scroll',update,{passive:true});if(window.ResizeObserver){const observer=new ResizeObserver(()=>{if(!root.isConnected){observer.disconnect();return}update()});observer.observe(track)}requestAnimationFrame(update)})}
function homeContentDefaults(){return {"selection": {"eyebrow": "KAHVALTINIZA YENİ BİR LEZZET", "title": "Sevdiğiniz peynirleri\nbirlikte keşfedin.", "body": "Beyaz peynirden kaşara, damak zevkinize uygun çeşitlerle kendi kahvaltınızı hazırlayın.", "image": "images/sofra.webp", "button": "Kahvaltı seçkilerini keşfedin →", "route": "seckiler", "enabled": true}, "hospitality": {"eyebrow": "PROFESYONEL MUTFAKLARDAN EVİNİZE", "title": "Deneyimimiz profesyonel,\ndavetimiz size.", "body": "Otellere ve profesyonel mutfaklara uzanan tedarik deneyimimizi tanıyın. İşletmenize uygun ürün ve gramaj seçeneklerini birlikte değerlendirelim.", "image": "", "button": "Kurumsal Maya’yı tanıyın →", "route": "kurumsal", "enabled": true}, "story": {"eyebrow": "MAYA’NIN HİKÂYESİ", "title": "Peynirin arkasındaki\ninsanları tanıyın.", "body": "Maya’nın geçmişini, ürünlerini ve profesyonel mutfaklardan evlere uzanan yolculuğunu keşfedin.", "image": "images/sofra.webp", "button": "Hikâyemizi okuyun →", "route": "hikayemiz", "enabled": true}, "delivery": {"eyebrow": "SİPARİŞTEN TESLİMATA", "title": "Alışverişten önce\naklınızda soru kalmasın.", "body": "Kargoya hazırlık takvimini, teslimat koşullarını ve paketleme bilgilerini inceleyin. Siparişinizle ilgili sorularınız için bize ulaşın.", "image": "", "button": "Teslimat bilgilerini inceleyin →", "route": "teslimat", "enabled": true}, "journal": {"eyebrow": "PEYNİR REHBERİ", "title": "Seçerken bilgi,\nkahvaltıda ilham.", "body": "", "image": "", "button": "Rehberi keşfedin →", "route": "rehber", "enabled": true}, "contact": {"eyebrow": "", "title": "Peynir seçerken yardıma mı ihtiyacınız var?", "body": "Ürün, gramaj ve teslimat sorularınız için yanınızdayız.", "image": "", "button": "Bize ulaşın →", "route": "iletisim", "enabled": true}, "pillar1": {"enabled": true, "eyebrow": "01", "title": "Ürünü tanıyarak seçin.", "body": "Gramaj, içerik ve kullanım bilgilerini alışverişten önce inceleyin.", "image": "", "button": "", "route": "iletisim"}, "pillar2": {"enabled": true, "eyebrow": "02", "title": "Damak zevkinize göre keşfedin.", "body": "Kahvaltı ve sıcak tarifler için peynir çeşitlerine göz atın.", "image": "", "button": "", "route": "iletisim"}, "pillar3": {"enabled": true, "eyebrow": "03", "title": "Sorularınızı bize iletin.", "body": "Ürün ve alışveriş sorularınız için yardım alanına kolayca ulaşın.", "image": "", "button": "", "route": "iletisim"}}}
function homeBlock(key){const d=homeContentDefaults()[key];return {...d,...(config.homeContent?.[key]||{})}}
function homeSurface(key,body,extra=''){const x=homeBlock(key),fallback={selection:'#eae9df',story:'#e5eadb',journal:'#f0e7d5'}[key]||'',background=/^#[0-9a-f]{6}$/i.test(x.background||'')?x.background:fallback,wide=x.fullWidth??(key==='journal');return `<section class="section home-surface home-${key} ${wide?'is-full':'container'} ${extra}" ${background?`style="--section-bg:${esc(background)}"`:''}><div class="home-surface-inner ${wide?'container':''}">${body}</div></section>`}
function homeEditorial(key){const x=homeBlock(key);if(x.enabled===false)return '';const img=x.image?mediaImage(x.image,x.title,{width:960}):'';const copy=`<div class="story-copy"><div class="eyebrow">${esc(x.eyebrow)}</div><h2 style="white-space:pre-line">${esc(x.title)}</h2><p>${esc(x.body)}</p>${x.button?a(x.route,esc(x.button),'text-link'):''}</div>`;return homeSurface(key,`<div class="${img?'split-story'+(x.imageSide==='right'?' image-right':''):'home-copy-panel'}">${img}${copy}</div>`)}
function home(){const j=homeBlock('journal'),c=homeBlock('contact');return `<main id="main">${heroSliderMarkup()}<nav class="category-strip" aria-label="Peynir kategorileri">${a('peynirler/beyaz','Beyaz Peynirler')}${a('peynirler/kasar','Kaşar Peynirleri')}${a('seckiler',esc(navigationLabel('seckiler','Kahvaltı Seçkileri')))}${a('peynirler','Tüm Ürünler →')}</nav>${homeProductRows()}${hotelReferences()}${homeEditorial('selection')}${homeEditorial('hospitality')}<section class="section container"><div class="pillars">${[1,2,3].map(i=>{const key='pillar'+i,x=homeBlock(key);return x.enabled===false?'':`<div class="pillar" ${/^#[0-9a-f]{6}$/i.test(x.background||'')?`style="background:${esc(x.background)}"`:''}><span>${esc(x.eyebrow)}</span>${x.image?mediaImage(x.image,x.title):''}<h3>${esc(x.title)}</h3><p>${esc(x.body)}</p>${x.button?a(x.route,esc(x.button),'text-link'):''}</div>`}).join('')}</div></section>${homeEditorial('story')}${homeEditorial('delivery')}${promotion()}${j.enabled!==false?homeSurface('journal',`<div class="section-head"><div><div class="eyebrow">${esc(j.eyebrow)}</div><h2 style="white-space:pre-line">${esc(j.title)}</h2><p>${esc(j.body)}</p></div>${j.button?a(j.route,esc(j.button),'text-link'):''}</div>${j.image?mediaImage(j.image,j.title):''}${journal(true)}`):''}${c.enabled!==false?homeSurface('contact',`<div class="contact-band"><div><div class="eyebrow">${esc(c.eyebrow)}</div><h3>${esc(c.title)}</h3><p>${esc(c.body)}</p>${c.image?mediaImage(c.image,c.title):''}</div>${c.button?a(c.route,esc(c.button),'btn secondary'):''}</div>`):''}</main>`}

const fallbackArticles=[{image:'images/sofra.webp',alt:'Maya arşivinden peynirlerle hazırlanmış kahvaltı sofrası',id:'otel-kahvaltisi',title:'Evde güzel bir kahvaltı sofrası.',tag:'SOFRA',intro:'Az sayıda, birbirini tamamlayan peynirle kendi kahvaltınızı hazırlayın.'},{image:'images/eski-kasar.webp',alt:'Peynir seçimini anlatan kaşar sunumu',id:'peynir-secimi',title:'Sofranıza hangi peynir yakışır?',tag:'SEÇİM',intro:'Peyniri yalnız adıyla değil, kullanımınız ve damak zevkinizle birlikte düşünün.'},{image:'images/beyaz.webp',alt:'Beyaz peynirin doku ve servis görünümü',id:'saklama',title:'Paket açıldıktan sonra.',tag:'KULLANIM',intro:'Her ürünün saklama bilgisi kendi etiketinde. Alışverişten sonra da onu esas alın.'}];
const articles=(window.MAYA_SERVER?.pages||[]).filter(p=>p.type==='blog').map(p=>({...p,intro:p.excerpt||p.body.slice(0,140),tag:p.tag||'REHBER',image:p.image||'images/sofra.webp',alt:p.title}));if(!articles.length)articles.push(...fallbackArticles);
function journal(carousel=false){const cards=articles.map(x=>`<article class="journal-card">${a('rehber/'+x.id,`<div class="journal-image">${x.image?mediaImage(x.image,x.alt||x.title):''}</div>`)}<div class="journal-copy"><div class="eyebrow">${esc(x.tag)}</div><h3>${a('rehber/'+x.id,esc(x.title))}</h3><p>${esc(x.intro)}</p>${a('rehber/'+x.id,'Keşfet →','text-link')}</div></article>`).join('');return carousel?`<div class="home-journal-carousel"><div class="journal-carousel-controls"><button type="button" data-journal-prev aria-label="Önceki rehber yazıları">←</button><button type="button" data-journal-next aria-label="Sonraki rehber yazıları">→</button></div><div class="journal-grid journal-carousel-track" tabindex="0" role="region" aria-label="Peynir rehberi yazıları">${cards}</div></div>`:`<div class="journal-grid">${cards}</div>`}
function setupJournalCarousel(){const root=document.querySelector('.home-journal-carousel');if(!root)return;const track=root.querySelector('.journal-carousel-track'),prev=root.querySelector('[data-journal-prev]'),next=root.querySelector('[data-journal-next]');const update=()=>{prev.disabled=track.scrollLeft<2;next.disabled=track.scrollLeft>=track.scrollWidth-track.clientWidth-2;root.querySelector('.journal-carousel-controls').hidden=track.scrollWidth<=track.clientWidth+2};const step=()=>track.querySelector('.journal-card').getBoundingClientRect().width+28;prev.onclick=()=>track.scrollBy({left:-step(),behavior:'smooth'});next.onclick=()=>track.scrollBy({left:step(),behavior:'smooth'});track.addEventListener('scroll',update,{passive:true});track.addEventListener('keydown',e=>{if(e.target!==track||!['ArrowLeft','ArrowRight'].includes(e.key))return;e.preventDefault();track.scrollBy({left:(e.key==='ArrowRight'?1:-1)*step(),behavior:'smooth'})});let drag=null,moved=false;track.addEventListener('pointerdown',e=>{if(e.pointerType!=='mouse'||e.button!==0)return;drag={x:e.clientX,left:track.scrollLeft,id:e.pointerId};moved=false});track.addEventListener('pointermove',e=>{if(!drag)return;const delta=e.clientX-drag.x;if(Math.abs(delta)>6&&!moved){moved=true;track.setPointerCapture(drag.id);track.classList.add('dragging')}if(moved){e.preventDefault();track.scrollLeft=drag.left-delta}});const finish=()=>{if(drag&&track.hasPointerCapture(drag.id))track.releasePointerCapture(drag.id);drag=null;track.classList.remove('dragging')};track.addEventListener('pointerup',finish);track.addEventListener('pointercancel',finish);track.addEventListener('lostpointercapture',finish);track.addEventListener('dragstart',e=>e.preventDefault());track.addEventListener('click',e=>{if(moved){e.preventDefault();e.stopPropagation();moved=false}},true);if(window.ResizeObserver){const observer=new ResizeObserver(()=>{if(!root.isConnected){observer.disconnect();return}update()});observer.observe(track)}requestAnimationFrame(update)}
function promotion(){const campaign=(window.MAYA_SERVER?.campaigns||[]).find(c=>c.active);const p=MAYA_CATALOG.find(x=>oldPrice(x));if(!p||!campaign)return '';return `<section class="promo-banner"><img src="assets/images/hero.webp" alt="Kampanya için peynirli kahvaltı sunumu" width="1600" height="900" loading="lazy"><div class="promo-shade"></div><div class="promo-copy"><div class="eyebrow">MAYA’DAN SOFRANIZA</div><h2>${esc(campaign.title)}</h2><p>${esc(p.name)} · 500 g</p><div class="promo-price"><del>${money(oldPrice(p))}</del><strong>${money(p.price)}</strong></div>${a('urun/'+p.id,'Ürünü keşfedin ↗','btn promo-btn')}</div></section>`}
function storyPage(){const page=window.MAYA_SERVER?.pages?.find(x=>x.id==='hikayemiz');if(page)return managedPage(page,true);return `<main id="main" class="brand-story"><div class="container"><div class="crumb">${a('anasayfa','Ana sayfa')} / Maya’nın Hikâyesi</div><section class="brand-story-hero"><div><div class="eyebrow">SOFRADAN SOFRAYA</div><h1>Bir sofradan<br>fazlası.</h1><p>Maya’nın hikâyesi, 1970’lerin başında İstanbul Üsküdar’da üç tekerlekli bir peynir arabasıyla başlıyor. Zamanla büyüyen bu yolculuğun merkezinde peynir ve sofralarla kurulan bağ var.</p><div class="actions">${a('peynirler','Peynirlerimizi keşfedin ↗','btn')}${a('kurumsal','Kurumsal Maya →','text-link')}</div></div><img src="assets/images/sofra.webp" alt="Maya arşivinden bir kahvaltı sofrası" width="1200" height="900"></section></div><section class="section story-band"><div class="container story-text-layout"><h2>Üsküdar’dan<br>sofranıza.</h2><div><p>Küçük bir işletmeden gelişen tedarik tecrübesine uzanan Maya, geçmişten gelen peynir bilgisini bugün ev sofralarıyla buluşturuyor. Beyaz peynirden kaşara uzanan seçkimizde, kahvaltınıza ve mutfağınıza eşlik edecek lezzetleri keşfedebilirsiniz.</p></div></div></section><section class="section container"><div class="pillars"><div class="pillar"><span>01</span><h3>Tanışın.</h3><p>Ürününüzü seçmeden önce açıklamalarını ve gerçek bilgilerini inceleyin.</p></div><div class="pillar"><span>02</span><h3>Keşfedin.</h3><p>Kahvaltınız ve tarifleriniz için peynir çeşitlerine göz atın.</p></div><div class="pillar"><span>03</span><h3>Konuşalım.</h3><p>Tüketici ve kurumsal talepleriniz için bizimle iletişime geçin.</p></div></div></section></main>`}
function guidePage(){return `<main id="main" class="guide-page"><section class="guide-intro container"><div class="crumb">${a('anasayfa','Ana sayfa')} / Peynir Rehberi</div><div class="section-head"><div><div class="eyebrow">SOFRAYA BİRAZ İLHAM</div><h1>Peynir Rehberi.</h1></div><p>Seçerken, sofrayı kurarken, paket açıldıktan sonra. Peynirle ilgili merak ettikleriniz için bir başlangıç.</p></div></section><section class="section journal-band"><div class="container">${journal()}</div></section><section class="section container"><div class="contact-band"><div><h3>Şimdi sofranıza yakışanı bulun.</h3><p>Rehberlerden ürünlere, kendi kahvaltınızı keşfedin.</p></div>${a('peynirler','Peynirleri keşfet ↗','btn')}</div></section></main>`}
function catalog(cat='all',isSet=false){const list=cat==='all'?MAYA_CATALOG:MAYA_CATALOG.filter(p=>p.category===cat);return `<main id="main" class="container"><div class="crumb">${a('anasayfa','Ana sayfa')} / Peynirler</div><section class="catalog-intro"><div class="eyebrow">MAYA’DAN SOFRANIZA</div><h1>${isSet?'Kahvaltınızı keşfedin.':cat==='beyaz'?'Beyaz peynirler.':cat==='kasar'?'Kaşar peynirleri.':'Peynirlerimiz.'}</h1><p>${isSet?'Peynirlerinizi tek tek seçin, kendi kahvaltı sofranızı oluşturun.':'Sade bir kahvaltıdan özenle hazırlanan sofralara. Kendi lezzetinizi bulun.'}</p></section><div class="catalog-tools"><div class="chips">${[['all','Tüm peynirler'],...(window.MAYA_SERVER?.categories||[]).map(c=>[c.id,c.name])].map(([id,text])=>a('peynirler/'+id,text,'chip '+(id===cat?'selected':''))).join('')}</div><select id="sort" aria-label="Ürünleri sırala"><option value="default">Önerilen sıralama</option><option value="up">Fiyat: düşükten yükseğe</option><option value="down">Fiyat: yüksekten düşüğe</option></select></div><div id="catalog-products" class="product-grid">${list.map(card).join('')}</div><div class="bottom-gap"></div><section class="section contact-band"><div><h3>Seçerken aklınıza takılanlar?</h3><p>Ürün detaylarına göz atın veya bize sorun.</p></div><button class="btn secondary" data-ai>Alışveriş asistanını aç</button></section></main>`}
function dateParts(now=new Date()){const p=new Intl.DateTimeFormat('en-CA',{timeZone:'Europe/Istanbul',year:'numeric',month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit',hourCycle:'h23'}).formatToParts(now);return Object.fromEntries(p.map(x=>[x.type,x.value]))}
function shippingEstimate(now=new Date()){const s=config.shipping;if(!s.enabled||!s.days.length)return null;const z=dateParts(now);let d=new Date(Date.UTC(+z.year,+z.month-1,+z.day));const currentMinutes=+z.hour*60+ +z.minute;const [h,m]=s.cutoff.split(':').map(Number);if(!Number.isFinite(h)||!Number.isFinite(m))return null;const before=currentMinutes<h*60+m;let lead=Math.max(0,Number(s.leadDays)||0);if(!before)d.setUTCDate(d.getUTCDate()+1);let loops=0;const ok=v=>s.days.includes(v.getUTCDay())&&!s.blackouts.includes(v.toISOString().slice(0,10));while((!ok(d)||lead>0)&&loops++<370){if(ok(d)&&lead>0)lead--;d.setUTCDate(d.getUTCDate()+1)}if(loops>=370)return null;const arrive=offset=>{const x=new Date(d);let n=0;while(n<offset){x.setUTCDate(x.getUTCDate()+1);if([1,2,3,4,5].includes(x.getUTCDay()))n++}return x};const fmt=x=>new Intl.DateTimeFormat('tr-TR',{day:'numeric',month:'long',timeZone:'UTC'}).format(x);return {dispatch:fmt(d),arrival:`${fmt(arrive(Number(s.transitMin)||1))} – ${fmt(arrive(Number(s.transitMax)||3))}`,before,remaining:Math.max(0,h*60+m-currentMinutes)}}
function dispatchHTML(){const e=shippingEstimate();if(!e)return `<div class="dispatch">${a('teslimat','Gönderim ve teslimat bilgilerini inceleyin →')}</div>`;return `<div class="dispatch"><strong>${config.shipping.demo?'Örnek gönderim planı · ':''}${e.before?'Saat '+esc(config.shipping.cutoff)+' öncesi verilen siparişler için:':'Bir sonraki gönderim planı:'}</strong><span>Tahmini kargoya veriliş: <b>${e.dispatch}</b></span><br><span>Tahmini teslimat: ${e.arrival}</span><small>Kargoya veriliş ve teslimat farklı tarihlerdir. Plan tahminidir; canlı gönderim taahhüdü değildir.</small></div>`}
function productTabs(p){const tabs=[['about','Ürün hakkında',p.details,p.description||''],['ingredients','İçerik',p.ingredients,'İçerik bilgisi için ürün etiketini inceleyin.'],['allergens','Alerjen',p.allergens,'Alerjen bilgisi için ürün etiketini inceleyin.'],['storage','Saklama',p.storage,'Saklama koşulları için ürün etiketini inceleyin.']];return `<div class="product-tabs"><div class="tab-list" role="tablist" aria-label="Ürün bilgileri">${tabs.map(([id,title],i)=>`<button type="button" role="tab" id="tab-${id}" data-tab="${id}" aria-controls="panel-${id}" aria-selected="${i===0}" tabindex="${i===0?0:-1}">${title}</button>`).join('')}</div>${tabs.map(([id,,text,fallback],i)=>`<div class="tab-panel" role="tabpanel" id="panel-${id}" data-panel="${id}" aria-labelledby="tab-${id}" ${i?'hidden':''}>${text&&String(text).trim()?bodyParagraphs(text):'<p>'+esc(fallback)+'</p>'}</div>`).join('')}</div>`}
function selectProductTab(name){const root=document.querySelector('.product-tabs');if(!root)return;root.querySelectorAll('[role=tab]').forEach(b=>{const on=b.dataset.tab===name;b.setAttribute('aria-selected',String(on));b.tabIndex=on?0:-1});root.querySelectorAll('[role=tabpanel]').forEach(panel=>{panel.hidden=panel.dataset.panel!==name})}
function assuranceMarkup(){const symbols=['<path d="M12 3 4 7.5v9L12 21l8-4.5v-9L12 3Z"/><path d="m4 7.5 8 4.5 8-4.5M12 12v9"/>','<path d="M12 3 5 6v5c0 4.5 3 8 7 10 4-2 7-5.5 7-10V6l-7-3Z"/><path d="m9 12 2 2 4-4"/>','<path d="M5 19c0-8 5-13 14-14 0 9-5 14-13 14"/><path d="M5 19c3-5 6-8 10-10"/>'];const items=(config.badges?.length?config.badges:assuranceDefaults()).filter(x=>x.verified&&x.title&&x.text).slice(0,3);if(!items.length)return '';return `<div class="assurance-card">${items.map((x,i)=>`<div class="assurance-row"><span class="assurance-icon" aria-hidden="true"><svg viewBox="0 0 24 24">${symbols[i]}</svg></span><div><h4>${esc(x.title)}</h4><p>${esc(x.text)}</p></div></div>`).join('')}</div>`}
function detail(id){const p=product(id);if(!p)return `<main id="main" class="container section"><h1>Ürün bulunamadı.</h1>${a('peynirler','Peynirleri keşfedin','btn')}</main>`;if(!p.weights.includes(selectedWeight))selectedWeight=p.weights[0];const related=window.MAYA_SERVER?.crossSell?.find(x=>x.product===p.id);const other=MAYA_CATALOG.find(x=>x.id===related?.related);return `<main id="main" class="container"><div class="crumb">${a('anasayfa','Ana sayfa')} / ${a('peynirler',esc(navigationLabel('peynirler','Peynirler')))} / ${esc(p.name)}</div><div class="product-layout">${productGallery(p)}<section class="product-detail"><div class="eyebrow">MAYA PEYNİR</div><h1>${esc(p.name)}</h1><p class="description">${esc(p.description)}</p><div id="purchase-anchor"><p class="weight-label">GRAMΑJ SEÇİN</p><div class="weights">${p.weights.map(w=>`<button class="weight ${w===selectedWeight?'active':''}" data-weight="${w}" aria-pressed="${w===selectedWeight}">${w===1000?'1 kg':w+' g'}</button>`).join('')}</div><div class="product-price" id="product-price">${priceMarkup(p,selectedWeight)}</div><div class="purchase"><div class="qty"><button data-qty="-1" aria-label="Adedi azalt">−</button><span id="quantity">${quantity}</span><button data-qty="1" aria-label="Adedi artır">+</button></div><button class="btn" data-detail-add="${p.id}" ${Number(p.stock)<=0?'disabled':''}>${Number(p.stock)>0?'Sepete ekle':'Stokta yok'} <span id="buy-total">${money(price(p,selectedWeight)*quantity)}</span></button></div></div><div id="shipping-estimate">${dispatchHTML()}</div>${config.videoUrl?'<button class="detail-link" data-video>Üretim videoları <span>▷</span></button>':''}${assuranceMarkup()}${productTabs(p)}${other?crossSellMarkup(p,other,related):''}</section></div>${productReviews(p)}<section class="section"><div class="section-head"><div><div class="eyebrow">SOFRANIZI TAMAMLAYIN</div><h2>Birlikte keşfedin.</h2></div></div><div class="product-grid">${MAYA_CATALOG.filter(x=>x.id!==p.id).slice(0,4).map(card).join('')}</div></section><div class="sticky-buy" id="sticky-buy"><div><strong>${esc(p.name)}</strong><small id="sticky-price">${selectedWeight===1000?'1 kg':selectedWeight+' g'} · ${money(price(p,selectedWeight))}</small></div><button class="btn" data-detail-add="${p.id}" ${Number(p.stock)<=0?'disabled':''}>${Number(p.stock)>0?'Sepete ekle':'Stokta yok'}</button></div><div class="bottom-gap"></div></main>`}
function cartPage(){return `<main id="main" class="container"><div class="crumb">${a('anasayfa','Ana sayfa')} / Sepet</div><h1 class="page-heading">Sepetiniz.</h1>${!cart.length?`<div class="empty"><h2>Sofranız için henüz bir seçim yok.</h2><p>Peynirlerimizi birlikte keşfedelim.</p>${a('peynirler','Peynirleri keşfet ↗','btn')}</div>`:`<div class="cart-layout"><div>${cart.map((x,i)=>{const p=product(x.id);return `<div class="cart-line">${imageSmall(p)}<div><h3>${a('urun/'+p.id,esc(p.name))}</h3><p>${x.weight===1000?'1 kg':x.weight+' g'} · ${x.qty} adet</p><div class="qty" style="width:105px"><button data-cart-qty="${i},-1" aria-label="Adedi azalt">−</button><span>${x.qty}</span><button data-cart-qty="${i},1" aria-label="Adedi artır">+</button></div><button class="remove" data-remove="${i}">Kaldır</button></div><span class="price" data-cart-line-price="${i}">${cartLinePriceMarkup(i)}</span></div>`}).join('')}<p class="help">Ürünlerinizi ve adetlerini ödeme öncesinde kontrol edebilirsiniz.</p></div><aside class="panel"><h2>Sipariş özeti</h2><div id="cart-quote-totals">${totals()}</div>${a('odeme','Siparişi tamamla →','btn full')}<p class="help">Ödeme işleminiz güvenli ödeme sağlayıcısında tamamlanır.</p></aside></div>`}<section class="section">${a('peynirler','← Alışverişe devam et','text-link')}</section></main>`}
function totals(){return `<div class="totals"><span>Ara toplam</span><span>${money(subtotal())}</span></div><div class="totals"><span>Kargo bedeli</span><span>${shipFee()===0?'Ücretsiz':money(shipFee())}</span></div>${vatMarkup()}<div class="totals total"><span>Toplam</span><span>${money(subtotal()+shipFee())}</span></div>`}
function checkout(){if(!cart.length)return cartPage();return `<header class="checkout-header">${a('anasayfa',storeLogoMarkup(),'logo')}<div id="checkout-account-status">${window.MAYA_SERVER?.customer?`<span>${esc(MAYA_SERVER.customer.name)} olarak giriş yaptınız.</span> ${a('hesabim','Hesabım','text-link')}`:a('giris','Hesabınız var mı? Giriş yap →','text-link checkout-login')}</div></header><main id="main" class="checkout-shell"><div class="checkout-form"><section class="checkout-step active" data-step="1"><h2><span class="step-no">1</span>Adres<button class="step-done" data-step-edit="1" hidden>Düzenle</button></h2><div class="step-body"><form id="address-form"><label>İletişim e-postası<input type="email" required autocomplete="email" placeholder="ornek@example.com" name="email"></label><label class="checkbox"><input name="marketing" type="checkbox">Kampanyalardan haberdar olmak istiyorum. (İsteğe bağlı)</label><h3 style="font-size:24px;margin:30px 0 20px">Teslimat adresi</h3><div class="fields"><label>Ad<input required name="name" autocomplete="given-name"></label><label>Soyad<input required name="surname" autocomplete="family-name"></label><label class="span2">Adres<input required name="address" autocomplete="street-address"></label><label>Apartman / daire<input name="address2" autocomplete="address-line2"></label><label>Posta kodu<input name="postal" inputmode="numeric" autocomplete="postal-code"></label><label>İl<input required name="city" autocomplete="address-level1"></label><label>İlçe<input required name="district" autocomplete="address-level2"></label><label class="span2">Telefon<input type="tel" required name="phone" autocomplete="tel" placeholder="+90"></label></div><label class="checkbox"><input type="checkbox" id="different-invoice">Fatura adresim farklı</label><div id="invoice-fields" hidden><label>Fatura adresi<textarea id="invoice-address"></textarea></label></div><button class="btn full" type="submit">Kargo ile devam et →</button></form></div></section><section class="checkout-step" data-step="2"><h2><span class="step-no">2</span>Kargo<button class="step-done" data-step-edit="2" hidden>Düzenle</button></h2><div class="step-body" hidden><label class="shipping-choice"><input type="radio" name="delivery" checked><span>Standart gönderim · ${shipFee()===0?'Ücretsiz':money(shipFee())}<br><small>Gönderim koşulları teslimat bilgilerine göre uygulanır.</small></span></label>${dispatchHTML()}<button class="btn full" data-next-payment>Ödeme ile devam et →</button></div></section><section class="checkout-step" data-step="3"><h2><span class="step-no">3</span>Ödeme</h2><div class="step-body" hidden><div id="payment-area"><p>Ödeme formu güvenli bağlantıyla açılır. Kart bilgileriniz mağazamızda saklanmaz.</p></div><label class="checkbox"><input type="checkbox" id="sale-terms">${a('mesafeli-satis','Ön bilgilendirme ve mesafeli satış koşullarını')} okudum ve kabul ediyorum.</label><button class="btn full" data-pay>Güvenli ödemeye geç →</button><p id="checkout-error" class="help" role="alert"></p></div></section></div><aside class="checkout-summary"><button class="summary-toggle" aria-expanded="false" data-summary><span>Sipariş özetini göster / gizle</span><strong>${money(subtotal()+shipFee())}</strong></button><div class="summary-content"><h2 class="checkout-summary-title">Sipariş özeti</h2><div id="checkout-summary-items">${checkoutItemsMarkup()}</div><div class="checkout-extras"><div class="checkout-coupon"><label for="coupon">İndirim kodu</label><div><input id="coupon" placeholder="Kodunuz varsa yazın" autocomplete="off"><button type="button" class="btn secondary" data-coupon>Uygula</button></div></div>${regularDeliveryCheckoutMarkup()}<label class="checkout-order-note" for="order-note">Sipariş notunuz<textarea id="order-note" rows="4" maxlength="1000" placeholder="Siparişinizle ilgili bize iletmek istediğiniz bir not var mı?"></textarea></label></div>${totals()}<p class="help">Adres bilgileriniz yalnız sipariş ve teslimat işlemleri için kullanılır.</p></div></aside></main>`}
function auth(){return `<main id="main" class="container account-entry"><div class="account-entry-heading"><div class="eyebrow">MAYA HESABINIZ</div><h1>Maya’ya hoş geldiniz.</h1><p>Sofranıza eşlik eden lezzetleri keşfedin, siparişlerinizi kolayca takip edin.</p></div><div class="account-entry-grid"><section class="account-entry-panel"><h2>Hesabınız var mı?</h2><p>Bilgilerinizle giriş yapın.</p><button type="button" class="google-auth-button" data-google>${googleBrandIcon()}<span>Google ile giriş yap</span></button><div class="auth-divider"><span>veya e-posta ile</span></div><form id="login-form"><label>E-posta<input type="email" required name="email" autocomplete="email" placeholder="ornek@sirket.com"></label><label>Şifre<span class="password-control"><input name="password" type="password" required autocomplete="current-password"><button type="button" class="password-eye" aria-label="Şifreyi göster/gizle" data-toggle-pw tabindex="-1">${eyeIcon(true)}</button></span></label><button class="btn full" type="submit">Giriş yap</button></form><button type="button" class="text-link forgot-link" data-forgot>Şifremi unuttum</button></section><section class="account-entry-panel" id="new-member"><h2>Yeni Hesap Aç</h2><button type="button" class="google-auth-button" data-google>${googleBrandIcon()}<span>Google ile giriş yap</span></button><div class="auth-divider"><span>veya e-posta ile</span></div><form id="register-form"><label>Ad soyad<input name="name" required maxlength="160" autocomplete="name"></label><label>E-posta adresi<input name="email" type="email" required autocomplete="email" placeholder="ornek@sirket.com"></label><label>Telefon numarası<div class="phone-dropdown-group"><div class="phone-country-dropdown"><select name="phoneCountry" aria-label="Ülke kodu"><option value="+90" selected>Türkiye (+90)</option></select><span class="dropdown-chevron" aria-hidden="true"><svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="m6 9 6 6 6-6"/></svg></span></div><input name="phone" type="tel" inputmode="numeric" placeholder="532 123 45 67" required autocomplete="tel-national" aria-describedby="register-phone-help"></div></label><small id="register-phone-help" class="form-helper-text">Ülke kodunu seçin, ardından telefon numaranızı yazın.</small><label>Şifreniz<span class="password-control"><input name="password" type="password" required minlength="8" autocomplete="new-password" placeholder="••••••••"><button type="button" class="password-eye" aria-label="Şifreyi göster/gizle" data-toggle-pw tabindex="-1">${eyeIcon(true)}</button></span></label><small class="form-helper-text">En az 8 karakter kullanın.</small><label>Şifreyi tekrar yaz<span class="password-control"><input name="passwordConfirm" type="password" required minlength="8" autocomplete="new-password"><button type="button" class="password-eye" aria-label="Şifreyi göster/gizle" data-toggle-pw tabindex="-1">${eyeIcon(true)}</button></span></label>${membershipCheckboxes()}<p id="register-error" class="form-error" role="alert"></p><button type="submit" class="btn full">Hesap oluştur</button></form></section></div><p class="guest-link">${a('odeme','Üyeliksiz alışverişe devam et →','text-link')}</p></main>`}
function corporate(){const corporatePage=window.MAYA_SERVER?.pages?.find(x=>x.id==='kurumsal');return `<main id="main" class="container corporate-page"><div class="crumb">${a('anasayfa','Ana sayfa')} / Kurumsal</div><section class="section corporate-hero"><div><div class="eyebrow">PROFESYONEL SOFRALAR İÇİN</div><h1>Maya ile<br>tanışalım.</h1><p>Otel, restoran ve profesyonel mutfaklar için ürün ve tedarik taleplerinizi birlikte değerlendirelim.</p><a href="#corporate-form" class="btn" data-scroll-form>Kurumsal iletişim ↗</a></div><img src="assets/images/sofra.webp" alt="Maya peynirleriyle kahvaltı sunumu" width="900" height="900"></section>${corporatePage?`<section class="section corporate-managed"><div class="managed-body">${bodyParagraphs(corporatePage.body)}</div></section>`:''}<section class="section corporate-editorial"><div class="section-head"><h2>Profesyonel mutfaklarla<br>aynı sofrada.</h2><p>Geçmişten gelen tedarik deneyimimizi otel, restoran ve işletmelerin ürün ihtiyaçlarıyla buluşturuyoruz. Talebinizi paylaşın; ürün, gramaj ve teslimat planını birlikte değerlendirelim.</p></div><div class="pillars"><article class="pillar"><span>01</span><h3>Ürün seçimi</h3><p>Kahvaltı servisi ve sıcak mutfak kullanımına göre beyaz peynir ve kaşar seçeneklerini birlikte inceleyin.</p></article><article class="pillar"><span>02</span><h3>İşletmenize uygun plan</h3><p>Gramaj, sipariş miktarı ve teslimat beklentinizi bize iletin. Kurumsal tedarik görüşmesini ihtiyaçlarınıza göre hazırlayalım.</p></article><article class="pillar"><span>03</span><h3>Doğrudan iletişim</h3><p>Yeni ürün, numune veya düzenli tedarik taleplerinizi kurumsal formdan paylaşabilirsiniz.</p></article></div></section>${hotelReferences()}<section class="section corporate-contact" id="corporate-form"><div class="content-page"><div class="eyebrow">KURUMSAL İLETİŞİM</div><h2>Sizi dinliyoruz.</h2><form id="inquiry-form" class="panel" style="margin-top:30px"><div class="fields"><label>Ad soyad<input required name="name" autocomplete="name"></label><label>Firma / otel<input required name="company" autocomplete="organization"></label><label>E-posta<input type="email" required name="email" autocomplete="email"></label><label>Telefon<input type="tel" name="phone" autocomplete="tel"></label><label class="span2">Talebiniz<textarea name="body" required></textarea></label></div><p class="help">${a('kvkk-aydinlatma','KVKK Aydınlatma Metni’ni inceleyin.')}</p><button class="btn" type="submit" style="margin-top:20px">Talebi ilet →</button></form></div></section></main>`}
function bodyParagraphs(body){return esc(body||'').split(/\n\s*\n/).map(p=>{const heading=p.match(/^(#{1,4})[ \t]+([^\n]+)(?:\n([\s\S]*))?$/);if(!heading)return '<p>'+p.replace(/\n/g,'<br>')+'</p>';const level=Math.max(2,heading[1].length);return '<h'+level+'>'+heading[2]+'</h'+level+'>'+(heading[3]?'<p>'+heading[3].replace(/\n/g,'<br>')+'</p>':'')}).join('')}
function mediaImage(path,alt,options={}){if(!path||!String(path).trim())return '';const uploaded=path?.startsWith('images/uploads/'),url=w=>'image.php?src='+encodeURIComponent(path)+'&amp;w='+w,widths=options.widths||[640,960,1440];return `<img class="${options.className||''}" src="${uploaded?url(options.width||960):'assets/'+esc(path)}" ${uploaded?`srcset="${widths.map(w=>url(w)+' '+w+'w').join(', ')}" sizes="${options.sizes||'(max-width: 760px) 100vw, 50vw'}"`:''} alt="${esc(alt)}" loading="${options.eager?'eager':'lazy'}" ${options.eager?'fetchpriority="high"':''} decoding="async" width="1200" height="800">`}
function managedPage(page,wide=false){const blog=page.type==='blog'||currentRoute().startsWith('rehber/');return `<main id="main" class="container section editorial-page"><div class="crumb">${a('anasayfa','Ana sayfa')} / ${blog?a('rehber',esc(navigationLabel('rehber','Peynir Rehberi')))+' / ':''}${esc(page.title)}</div><article class="editorial-article"><header><div class="eyebrow">${blog?'PEYNİR REHBERİ':'MAYA PEYNİR'}</div><h1>${esc(page.title)}</h1></header><div class="editorial-layout ${page.id==='hikayemiz'?'story-flow':''} ${page.image?'':'without-image'}">${page.image?`<figure>${mediaImage(page.image,page.title,{eager:true})}</figure>`:''}<div class="editorial-copy managed-body">${bodyParagraphs(page.body)}</div></div>${blog?`<div class="editorial-bottom">${a('rehber','← Diğer rehber yazıları','text-link')}${a('peynirler','Sofranız için peynir seçin →','btn secondary')}</div>`:''}</article></main>`}
function contentPage(type,id){if(type==='iletisim')return contactPage();if(type==='sss')return faqPage();const managed=window.MAYA_SERVER?.pages?.find(p=>p.id===(type==='rehber'?id:type));if(managed&&type!=='politikalar')return managedPage(managed);let title='',body='';if(type==='rehber'){const art=articles.find(x=>x.id===id);if(art)return managedPage({...art,body:art.body||art.intro});title='Yazı bulunamadı.';body=a('rehber','Rehbere dön →','btn')}
if(['kullanim-kosullari','kvkk-aydinlatma','mesafeli-satis','iptal-iade','cerez-politikasi'].includes(type)){title=({'kullanim-kosullari':'Kullanım Koşulları','kvkk-aydinlatma':'KVKK Aydınlatma Metni','mesafeli-satis':'Mesafeli Satış Sözleşmesi','iptal-iade':'İptal ve İade Koşulları','cerez-politikasi':'Çerez Politikası'}[type]);body='<p>Bu metin henüz yayınlanmadı. Bilgi için mağazamızla iletişime geçebilirsiniz.</p>'+a('iletisim','İletişim →','btn secondary')}
if(type==='teslimat'){title='Sofranıza ulaşırken.';body=`<p>Siparişinizin tahmini kargoya veriliş ve teslimat aralıkları ürün sayfasında ayrı gösterilir.</p>${dispatchHTML()}<h2>Kargo ücreti.</h2><p>${money(config.shippingFee)} gönderim bedeli uygulanır. ${money(config.freeShipping)} ve üzerindeki siparişlerde gönderim ücretsizdir.</p><p>Paketleme ve ürünün saklama koşullarıyla ilgili sorularınız için bize ulaşabilirsiniz.</p>${a('iletisim','Bize ulaşın →','btn secondary')}`}
if(type==='iletisim'){const c=config.contact||{};title='Sofranız için yanınızdayız.';body=`${c.business?'<p>'+esc(c.business)+'</p>':''}<p><a href="mailto:${esc(c.email||'info@mayapeynir.com')}">${esc(c.email||'info@mayapeynir.com')}</a></p>${c.phone?'<p>'+esc(c.phone)+'</p>':''}${c.address?'<p>'+esc(c.address)+'</p>':''}<form id="inquiry-form" class="panel"><label>Adınız<input name="name" required></label><label>E-posta<input name="email" type="email" required></label><label>Mesajınız<textarea name="body" required></textarea></label><button class="btn">Mesajı ilet →</button></form>`}
if(type==='politikalar'){title=managed?.title||'Gizlilik ve satış bilgileri';body=`${managed?bodyParagraphs(managed.body):''}<div class="policy-links">${[['kullanim-kosullari','Kullanım Koşulları'],['kvkk-aydinlatma','KVKK Aydınlatma Metni'],['mesafeli-satis','Mesafeli Satış Sözleşmesi'],['iptal-iade','İptal ve İade Koşulları'],['cerez-politikasi','Çerez Politikası']].map(([route,name])=>a(route,name+' →','detail-link')).join('')}</div><button class="btn secondary" data-consent>Çerez tercihlerimi yönet</button>`}
if(type==='takip'){title='Siparişinizi takip edin.';body=`<p>Hesabınıza giriş yaparak sipariş ve kargo durumunu görebilirsiniz. Misafir alışverişiniz için ödeme sonrasında verilen güvenli sipariş sayfasını kullanın.</p>${a('hesabim','Siparişlerime git →','btn')}`}
if(!title){title='Sayfa bulunamadı.';body=a('anasayfa','Ana sayfaya dön →','btn')}
return `<main id="main" class="container section"><article class="content-page"><h1>${esc(title)}</h1>${body}</article></main>`}
function https(url){try{const u=new URL(url);return u.protocol==='https:'?u.href:null}catch{return null}}
function drawer(title,body){closeDrawer();previousFocus=document.activeElement;$('#layers').innerHTML=`<div class="drawer-overlay" data-backdrop><section class="drawer" role="dialog" aria-modal="true" aria-label="${esc(title)}"><header class="drawer-head"><h2>${title}</h2><button class="close" data-close aria-label="Kapat">×</button></header><div class="drawer-body">${body}</div></section></div>`;document.body.classList.add('body-lock');$('#layers [data-close]').focus()}
function closeDrawer(){if(!$('#layers'))return;$('#layers').innerHTML='';document.body.classList.remove('body-lock');previousFocus?.focus?.()}
function documents(){const docs=config.certificates.filter(x=>x.verified&&https(x.url));drawer('Raporlar ve sertifikalar',`<p>Ürüne ve işletmeye ait doğrulanmış belgeler.</p>${docs.length?docs.map(x=>`<div class="document"><strong>${esc(x.title)}</strong><small>${esc(x.date)}</small><a class="text-link" href="${esc(https(x.url))}" target="_blank" rel="noopener noreferrer">Belgeyi aç ↗</a></div>`).join(''):'<div class="document"><strong>Henüz yayınlanmış belge yok.</strong><p class="help">Gerçek rapor ve sertifikalar panelden eklendiğinde burada listelenecek. Belge olmadan onay veya sertifika iddiası gösterilmez.</p></div>'}`)}
function ai(){drawer('Maya alışveriş asistanı',`<p>Ürün seçimi, kampanyalar ve teslimat hakkında sorularınızı sorun.</p><p class="demo-note">Maya’nın yapay zekâ destekli alışveriş yardımcısı. Yanıtlar güncel mağaza bilgilerine dayanır.</p>${['Peynir çeşitleri neler?','Güncel kampanyalar var mı?','Kargo ücreti ne kadar?','Ne zaman kargoya verilir?','Nasıl paketleniyor?'].map(x=>`<button class="question" data-ask="${x}">${x}</button>`).join('')}<div id="ai-answer" class="ai-answer">Bir soru seçin veya aşağıya yazın. Doğrulanmamış bilgi tahmin edilmez.</div><form id="ask-form"><label>Sorunuz<textarea id="ask-input" required placeholder="Ürün veya alışveriş hakkında sorun"></textarea></label><button type="submit" class="btn full">Sor →</button></form>`)}
async function answer(q){if(window.MAYA_SERVER){try{const result=await serverApi('assistant',{question:q});$('#ai-answer').textContent=result.answer;return}catch(e){$('#ai-answer').textContent=e.message;return}}let text;if(/kampanya|indirim/i.test(q))text='Şu anda kayıtlı bir indirim kampanyası yok. Kampanya yönetimi gerçek veri kaynağına bağlandığında asistan yayımlanmış ve geçerli kampanyaları okuyacak.';else if(/ücret|bedel|fiyat/i.test(q))text=`Yerel önizleme kargo bedeli ${money(config.shippingFee)}. ${money(config.freeShipping)} üzerindeki örnek sepetlerde ücretsiz. Bunlar canlı satış koşulları değil.`;else if(/ne zaman|kargoya|gönderim/i.test(q)){const e=shippingEstimate();text=e?`Örnek ayarlara göre tahmini kargoya veriliş ${e.dispatch}; tahmini teslimat ${e.arrival}. Bu bir canlı teslimat sözü değil.`:'Gönderim planı etkin değil; gerçek gönderim bilgisi henüz girilmedi.'}else if(/paket|soğuk/i.test(q))text='Doğrulanmış paketleme ve soğuk zincir koşulları henüz girilmedi. Bu bilgiyi varsayarak yanıtlayamam.';else if(/peynir|ürün|çeşit/i.test(q))text='Örnek katalogda '+MAYA_CATALOG.map(p=>p.name).join(', ')+' bulunuyor. Ayrıntılar ve fiyatlar geliştirme önizlemesidir.';else text='Bu yerel örnekte ürün, kargo ücreti, gönderim tarihi veya kampanya sorularını hazır düğmelerle inceleyebilirsiniz. Serbest GPT yanıtı henüz bağlı değil.';$('#ai-answer').textContent=text;$('#ai-answer').scrollIntoView({block:'nearest',behavior:'smooth'})}
function consent(){const c=safeRead('maya-consent',{});drawer('Çerez tercihleriniz',`<p>Mağazayı kullanmanız için gerekli işlemler ile isteğe bağlı ölçüm ve pazarlama tercihleri ayrı yönetilir.</p><p class="demo-note">Seçimlerinizi dilediğiniz zaman çerez tercihleri alanından değiştirebilirsiniz.</p>${[['necessary','Zorunlu','Sepet ve tercih gibi gerekli işlevler.'],['preferences','Tercihler','İsteğe bağlı kullanım tercihlerinin hatırlanması.'],['analytics','Analitik','İzinli ziyaret ve kullanım ölçümü.'],['marketing','Pazarlama','İzinli reklam ve kampanya ölçümü.']].map(([key,title,desc])=>`<div class="consent-row"><label class="checkbox"><input type="checkbox" name="consent-${key}" ${key==='necessary'?'checked disabled':c[key]?'checked':''}>${title}</label><p>${desc}</p></div>`).join('')}<p class="help">Zorunlu oturum çerezi: maya_session (tarayıcı oturumu). Sepet: maya-cart (siz temizleyene kadar). Tercih: maya-consent (siz değiştirene veya temizleyene kadar). Analitik izin verilirse yalnız sitemizde tutulan sınırlı olay ölçümü çalışır; reklam sağlayıcısı henüz bağlı değildir.</p><div class="cookie-actions"><button data-consent-save="reject">Tümünü reddet</button><button data-consent-save="selected">Tercihlerimi kaydet</button><button data-consent-save="accept">Tümünü kabul et</button></div>${a('politikalar','Politikaları incele →','text-link')}`)}
function banner(){if(localStorage.getItem('maya-consent'))return;const node=document.createElement('div');node.id='cookie-banner';node.className='cookie-banner';node.innerHTML='<div><h3>Tercih sizin.</h3><p>Gerekli işlevlerin yanında isteğe bağlı çerezleri siz seçin. Tercihlerinizi daha sonra da değiştirebilirsiniz.</p></div><div class="cookie-actions"><button data-consent>Çerezleri yönet</button><button data-consent-save="reject">Tümünü reddet</button><button data-consent-save="accept">Tümünü kabul et</button></div>';document.body.appendChild(node)}
function saveConsent(mode){const c={necessary:true,preferences:mode==='accept',analytics:mode==='accept',marketing:mode==='accept',version:'1',time:new Date().toISOString()};if(mode==='selected')for(const k of ['preferences','analytics','marketing'])c[k]=!!$(`[name="consent-${k}"]`)?.checked;localStorage.setItem('maya-consent',JSON.stringify(c));$('#cookie-banner')?.remove();closeDrawer();toast('Çerez tercihleriniz kaydedildi')}
function setStep(num){checkoutStep=num;$$('[data-step]').forEach(s=>{const n=Number(s.dataset.step);s.classList.toggle('active',n===num);s.querySelector('.step-body').hidden=n!==num;const b=s.querySelector('.step-done');if(b)b.hidden=n>=num});$(`[data-step="${num}"]`)?.scrollIntoView({block:'start',behavior:'smooth'})}
function render(){if(location.hash==='#yonetim'){location.href='admin.php';return}closeDrawer();const [route,id]=currentRoute().split('/');if(route==='corporate-form'||route==='main')return;applyTheme();const view=route==='not-found'?'<main id="main" class="container section"><h1>Sayfa bulunamadı.</h1>'+a('anasayfa','Ana sayfaya dön','btn')+'</main>':route==='anasayfa'?home():route==='peynirler'?catalog(id||'all'):route==='seckiler'?collectionPage():route==='duzenli-siparis'?regularOfferPage():route==='paket'?packageDetail(id):route==='urun'?detail(id):route==='sepet'?cartPage():route==='odeme'?checkout():route==='giris'?auth():route==='hesabim'?accountPage():route==='kayit'?registerPage():route==='sifre-yenile'?resetPage(id):route==='odeme-sonuc'?orderResult(id):route==='kurumsal'?corporate():route==='hikayemiz'?storyPage():route==='rehber'&&!id?guidePage():contentPage(route,id);$('#app').innerHTML=route==='odeme'&&cart.length?view:header()+view+footer();clearTimeout(window.mascotTimer);if(route!=='odeme'&&route!=='yonetim')window.mascotTimer=setTimeout(()=>{if(!document.querySelector('.chat-launch')&&$('#app'))$('#app').insertAdjacentHTML('beforeend','<button class="chat-launch mascot-launch" data-ai aria-label="Maya alışveriş asistanını aç"><picture><source media="(prefers-reduced-motion: reduce)" srcset="assets/images/mascots/maya-02-small.webp"><source type="image/webp" srcset="assets/images/mascots/maya-02-animated.webp"><img src="assets/images/mascots/maya-02.gif" alt="" width="96" height="96" loading="lazy" decoding="async" fetchpriority="low"></picture><span>Maya’ya sorun</span></button>')},2000);window.scrollTo(0,0);if(!window.MAYA_SERVER?.route)document.title=route==='urun'?(product(id)?.name||'Ürün bulunamadı')+' | Maya Peynir':'Maya Peynir | '+({anasayfa:'Sofranıza yakışan lezzetler',peynirler:'Peynirlerimiz',sepet:'Sepet',odeme:'Siparişinizi tamamlayın',giris:'Müşteri girişi',yonetim:'Yerel önizleme ayarları'}[route]||'Sofraya dair');if(route==='urun'&&product(id)){updateProduct();loadProductReviews(id)}if(route==='odeme'){checkoutStep=1;restoreAddress()}if((route==='odeme'||route==='sepet')&&cart.length)syncCartQuote();if(route==='hesabim')loadAccount();if(route==='odeme-sonuc')loadOrderResult(id);banner();connectGoogle();setupJournalCarousel();setupProductRows();setupHeroSlider();if(route==='duzenli-siparis')loadRegularOffer();}
function updateProduct(){const id=currentRoute().split('/')[1],p=product(id);$$('[data-weight]').forEach(b=>{b.classList.toggle('active',Number(b.dataset.weight)===selectedWeight);b.setAttribute('aria-pressed',Number(b.dataset.weight)===selectedWeight)});if($('#product-price'))$('#product-price').innerHTML=priceMarkup(p,selectedWeight)+'';if($('#quantity'))$('#quantity').textContent=quantity;if($('#buy-total'))$('#buy-total').textContent=money(price(p,selectedWeight)*quantity);$$('[data-detail-add]').forEach(b=>b.disabled=stockFor(p,selectedWeight)<=0);if($('#sticky-price'))$('#sticky-price').textContent=(selectedWeight===1000?'1 kg':selectedWeight+' g')+' · '+money(price(p,selectedWeight)*quantity)}
function sticky(){const anchor=$('#purchase-anchor'),bar=$('#sticky-buy');if(anchor&&bar)bar.classList.toggle('on',anchor.getBoundingClientRect().bottom<0)}
document.addEventListener('click',e=>{const el=e.target.closest('button,a');if(!el)return;if(el.matches('[data-close]'))closeDrawer();if(el.matches('[data-menu]'))drawer('Maya Peynir',`<nav style="display:flex;flex-direction:column;gap:25px;font-family:var(--serif);font-size:29px">${a('peynirler',esc(navigationLabel('peynirler','Peynirler')))}${a('seckiler',esc(navigationLabel('seckiler','Kahvaltı Seçkileri')))}${a('hikayemiz',esc(navigationLabel('hikayemiz','Hikâyemiz')))}${a('rehber',esc(navigationLabel('rehber','Peynir Rehberi')))}${a('kurumsal',esc(navigationLabel('kurumsal','Kurumsal')))}${a('giris','Hesabım')}${a('iletisim','İletişim')}</nav>`);if(el.matches('[data-search]'))drawer('Sofranız için arayın',`<label>Ürün adı<input id="search-input" type="search" placeholder="Peynir arayın" autofocus></label><div id="search-results">${MAYA_CATALOG.map(p=>`<p>${a('urun/'+p.id,esc(p.name),'text-link')}</p>`).join('')}</div>`);if(el.matches('[data-add]'))add(el.dataset.add,Number(el.dataset.addWeight)||500);if(el.matches('[data-detail-add]'))add(el.dataset.detailAdd,selectedWeight,quantity);if(el.matches('[data-gallery]'))selectGallery(Number(el.dataset.gallery));if(el.matches('[data-gallery-step]'))selectGallery(Number(document.querySelector('.product-gallery')?.dataset.index||0)+Number(el.dataset.galleryStep));if(el.matches('[data-tab]'))selectProductTab(el.dataset.tab);if(el.matches('[data-weight]')){selectedWeight=Number(el.dataset.weight);updateProduct()}if(el.matches('[data-qty]')){quantity=Math.max(1,Math.min(99,quantity+Number(el.dataset.qty)));updateProduct()}if(el.matches('[data-remove]')){const inDrawer=!!document.querySelector('.mini-cart');cart.splice(Number(el.dataset.remove),1);saveCart();if(inDrawer)cartDrawer();else render()}if(el.matches('[data-cart-qty]')){const [idx,d]=el.dataset.cartQty.split(',').map(Number);cart[idx].qty=Math.min(99,Math.max(1,cart[idx].qty+d));saveCart();if(document.querySelector('.mini-cart'))cartDrawer();else render()}if(el.matches('[data-ai]'))ai();if(el.matches('[data-ask]'))answer(el.dataset.ask);if(el.matches('[data-documents]'))documents();if(el.matches('[data-video]'))drawer('Üretim videoları',`<p>Üretim sürecine ait kayıtlı video bağlantısı.</p><a class="btn secondary" href="${esc(https(config.videoUrl)||'#')}" target="_blank" rel="noopener noreferrer">Videoyu aç ↗</a><p class="help">Haricî servis yeni sekmede açılır.</p>`);if(el.matches('[data-consent]')){e.preventDefault();consent()}if(el.matches('[data-consent-save]'))saveConsent(el.dataset.consentSave);if(el.matches('[data-summary]')){summaryExpanded=!summaryExpanded;$('.summary-content').classList.toggle('expanded',summaryExpanded);el.setAttribute('aria-expanded',summaryExpanded)}if(el.matches('[data-next-payment]'))setStep(3);if(el.matches('[data-step-edit]'))setStep(Number(el.dataset.stepEdit));if(el.matches('[data-pay]'))submitPayment(el);if(el.matches('[data-coupon]'))applyCoupon();if(el.matches('[data-google]'))googleLogin();if(el.matches('[data-forgot]'))drawer('Şifrenizi yenileyin','<form id="forgot-form"><label>E-posta<input name="email" type="email" required></label><button class="btn">Bağlantı gönder</button></form>');if(el.matches('[data-customer-logout]'))customerLogout();if(el.matches('[data-not-connected]'))toast('Bu servis henüz bağlanmadı; gerçek işlem yapılmadı.');if(el.matches('[data-scroll-form]')){e.preventDefault();$('#corporate-form').scrollIntoView({behavior:'smooth'})}if(el.matches('[data-reset-settings]')){localStorage.removeItem('maya-preview-settings');config=structuredClone(defaults);render();toast('Varsayılan önizleme ayarlarına dönüldü')}if(el.tagName==='A'&&el.getAttribute('href')?.startsWith('#')&&el.getAttribute('href')===location.hash)closeDrawer()});
document.addEventListener('click',e=>{if(e.target.matches('[data-backdrop]'))closeDrawer()});
document.addEventListener('input',e=>{if(e.target.id==='search-input'){const q=e.target.value.toLocaleLowerCase('tr-TR');const list=MAYA_CATALOG.filter(p=>p.name.toLocaleLowerCase('tr-TR').includes(q));$('#search-results').innerHTML=list.length?list.map(p=>`<p>${a('urun/'+p.id,esc(p.name),'text-link')}</p>`).join(''):'<p>Bu aramayla eşleşen ürün bulunamadı.</p>'}});
document.addEventListener('change',e=>{if(e.target.id==='different-invoice'){$('#invoice-fields').hidden=!e.target.checked;$('#invoice-address').required=e.target.checked}if(e.target.id==='sort'){const [,cat='all']=currentRoute().split('/');let list=cat==='all'? [...MAYA_CATALOG]:MAYA_CATALOG.filter(p=>p.category===cat);if(e.target.value==='up')list.sort((a,b)=>a.price-b.price);if(e.target.value==='down')list.sort((a,b)=>b.price-a.price);$('#catalog-products').innerHTML=list.map(card).join('')}});
document.addEventListener('submit',e=>{if(e.target.id==='address-form'){e.preventDefault();checkoutAddress=Object.fromEntries(new FormData(e.target));checkoutAddress.marketing=new FormData(e.target).has('marketing');checkoutAddress.invoice=$('#different-invoice')?.checked?$('#invoice-address').value:'';verifyCheckout()}if(e.target.id==='register-form'){e.preventDefault();registerCustomer(e.target)}if(e.target.id==='forgot-form'){e.preventDefault();forgotPassword(e.target)}if(e.target.id==='reset-form'){e.preventDefault();resetPassword(e.target)}if(e.target.id==='account-form'){e.preventDefault();updateAccount(e.target)}if(e.target.id==='login-form'){e.preventDefault();customerLogin(e.target)}if(e.target.id==='inquiry-form'){e.preventDefault();sendInquiry(e.target)}if(e.target.id==='ask-form'){e.preventDefault();answer($('#ask-input').value)}});
document.addEventListener('keydown',e=>{if(e.key==='Escape')closeDrawer();if(e.key==='Tab'&&$('.drawer')){const items=$$('.drawer button,.drawer a,.drawer input,.drawer select,.drawer textarea').filter(x=>!x.disabled&&x.offsetParent!==null);const first=items[0],last=items.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus()}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus()}}});
window.addEventListener('hashchange',()=>{selectedWeight=500;quantity=1;summaryExpanded=false;render()});window.addEventListener('scroll',sticky,{passive:true});window.addEventListener('resize',sticky);render();

function cartDrawer(){drawer('Sepetinizdeki ürünler',`<div class="mini-cart"><div class="mini-cart-items">${cart.length?cart.map((x,i)=>{const p=product(x.id);return `<article class="mini-cart-line">${imageSmall(p)}<div><strong>${a('urun/'+p.id,esc(p.name))}</strong><small>${x.weight===1000?'1 kg':x.weight+' g'}</small><div class="mini-cart-controls"><button data-cart-qty="${i},-1" aria-label="Adedi azalt">−</button><span>${x.qty}</span><button data-cart-qty="${i},1" aria-label="Adedi artır">+</button><button class="mini-remove" data-remove="${i}">Kaldır</button></div></div><span data-cart-line-price="${i}">${cartLinePriceMarkup(i)}</span></article>`}).join(''):'<p>Sepetiniz henüz boş.</p>'}</div><div class="mini-cart-bottom">${cart.length?`<div class="shipping-progress">${subtotal()<config.freeShipping?'Ücretsiz kargoya '+money(config.freeShipping-subtotal())+' kaldı.':'Ücretsiz kargo eşiğine ulaştınız.'}</div><label>Kupon kodu<input id="drawer-coupon" placeholder="Kupon kodunuz"></label><button class="text-link" style="background:none;color:inherit" data-coupon>Uygula</button><div id="drawer-quote-totals" aria-live="polite"><p>Sepet tutarı hesaplanıyor…</p></div><div class="mini-cart-actions">${a('sepet','Sepete git','btn secondary')}${a('odeme','Ödemeye geç →','btn')}</div>`:a('peynirler','Peynirleri keşfet →','btn')}</div></div>`);if(cart.length)syncCartQuote()}

async function serverApi(route,data){if(route==='quote'&&data&&!Object.hasOwn(data,'regularOfferToken')&&pendingRegularOffer()?.token)data={...data,regularOfferToken:pendingRegularOffer().token};if(!window.MAYA_SERVER)throw Error('Mağazayı sunucu adresinden açın.');const r=await fetch('api.php?r='+route,{method:data?'POST':'GET',credentials:'same-origin',headers:data?{'Content-Type':'application/json','X-CSRF-Token':MAYA_SERVER.csrf}:{},body:data?JSON.stringify(data):undefined});const j=await r.json();if(!r.ok){const error=Error(j.error||'İşlem tamamlanamadı.');error.status=r.status;throw error}return j}
async function customerLogin(form){try{const f=new FormData(form),r=await serverApi('login',{email:f.get('email'),password:f.get('password')});MAYA_SERVER.csrf=r.csrf;MAYA_SERVER.customer=r.user;toast('Giriş yaptınız.');afterCustomerLogin()}catch(e){toast(e.message)}}
async function sendInquiry(form){const button=form.querySelector('[type=submit]'),out=form.querySelector('[data-inquiry-result]');if(button?.disabled)return;try{if(button)button.disabled=true;if(out)out.textContent='Mesajınız gönderiliyor…';const f=new FormData(form),order=String(f.get('order')||'').trim();await serverApi('inquiry',{name:f.get('name'),email:f.get('email'),body:f.get('body'),topic:f.get('company')?'Kurumsal: '+f.get('company'):order?'Sipariş: '+order:'İletişim'});form.reset();if(out)out.textContent='Mesajınız alındı. Teşekkür ederiz.';toast('Mesajınız alındı. Teşekkür ederiz.')}catch(e){if(out)out.textContent=e.message;toast(e.message)}finally{if(button)button.disabled=false}}

function galleryPaths(p){return [...new Set([p.image,...(p.gallery||[])].filter(Boolean))]}
function productGallery(p){const paths=galleryPaths(p);return `<div class="product-gallery" data-index="0" data-product="${esc(p.id)}"><div class="gallery-stage" tabindex="0" role="region" aria-label="Ürün görselleri">${image(p,'product-main-image')}${paths.length>1?'<button type="button" class="gallery-arrow gallery-prev" data-gallery-step="-1" aria-label="Önceki görsel">‹</button><button type="button" class="gallery-arrow gallery-next" data-gallery-step="1" aria-label="Sonraki görsel">›</button><span class="gallery-position" aria-live="polite">1 / '+paths.length+'</span>':''}</div>${paths.length>1?`<div class="gallery-thumbs">${paths.map((path,i)=>`<button type="button" data-gallery="${i}" class="${i===0?'selected':''}" aria-label="${i+1}. görsel" aria-pressed="${i===0}"><img src="image.php?src=${encodeURIComponent(path)}&amp;w=320" alt="${esc(p.name)} · ${i+1}" loading="lazy"></button>`).join('')}</div>`:''}</div>`}
function selectGallery(index){const gallery=document.querySelector('.product-gallery');if(!gallery)return;const p=product(gallery.dataset.product),paths=galleryPaths(p);index=(index%paths.length+paths.length)%paths.length;gallery.dataset.index=index;const img=gallery.querySelector('.product-main-image');if(!img)return;const url='image.php?src='+encodeURIComponent(paths[index])+'&w='+(matchMedia('(max-width:760px)').matches?640:960);const next=new Image();gallery.classList.add('gallery-loading');next.onload=()=>{if(Number(gallery.dataset.index)!==index)return;img.removeAttribute('srcset');img.removeAttribute('sizes');img.src=url;img.alt=p.name+' · '+(index+1);gallery.classList.remove('gallery-loading')};next.onerror=()=>{gallery.classList.remove('gallery-loading');toast('Görsel yüklenemedi. Tekrar deneyin.')};next.src=url;gallery.querySelectorAll('[data-gallery]').forEach((b,i)=>{b.classList.toggle('selected',i===index);b.setAttribute('aria-pressed',i===index)});const position=gallery.querySelector('.gallery-position');if(position)position.textContent=(index+1)+' / '+paths.length}
document.addEventListener('touchstart',e=>{if(!e.target.closest('.gallery-stage'))return;galleryTouch={x:e.touches[0].clientX,y:e.touches[0].clientY}},{passive:true});
document.addEventListener('touchend',e=>{if(!galleryTouch)return;const dx=e.changedTouches[0].clientX-galleryTouch.x,dy=e.changedTouches[0].clientY-galleryTouch.y;galleryTouch=null;if(Math.abs(dx)>45&&Math.abs(dx)>Math.abs(dy)*1.3)selectGallery(Number(document.querySelector('.product-gallery')?.dataset.index||0)+(dx<0?1:-1))},{passive:true});
document.addEventListener('keydown',e=>{if(!e.target.closest('.product-gallery')||!['ArrowLeft','ArrowRight'].includes(e.key))return;e.preventDefault();selectGallery(Number(document.querySelector('.product-gallery').dataset.index||0)+(e.key==='ArrowRight'?1:-1))});
document.addEventListener('keydown',e=>{const tab=e.target.closest?.('[role=tab]');if(!tab||!['ArrowLeft','ArrowRight'].includes(e.key))return;const tabs=[...tab.parentElement.querySelectorAll('[role=tab]')],next=tabs[(tabs.indexOf(tab)+(e.key==='ArrowRight'?1:-1)+tabs.length)%tabs.length];e.preventDefault();next.focus();selectProductTab(next.dataset.tab)});

function heroPicture(h=config.hero||{}){const mobile=h.mobileImage||h.image||'images/hero.webp',fit=h.mobileFit==='cover'?'cover':'contain',position=['top','center','bottom'].includes(h.mobilePosition)?h.mobilePosition:'center';return `<picture class="hero-responsive" style="--mobile-hero-fit:${fit};--mobile-hero-position:${position}"><source media="(max-width:760px)" srcset="image.php?src=${encodeURIComponent(mobile)}&amp;w=640">${mediaImage(h.image||'images/hero.webp','Maya kahvaltı sofrası',{eager:true,width:1440})}</picture>`}
function crossSellMarkup(main,other,rule){const weight=Number(other.weights?.[0]||500),unit=price(other,weight),percent=rule?.active?Math.max(0,Math.min(50,Number(rule.discountPercent)||0)):0,discounted=Math.round(unit*(100-percent))/100;return `<aside class="cross cross-offer"><div class="eyebrow">SOFRANIZI TAMAMLAYIN</div><h3>${esc(rule?.title||'Sofranıza bir de…')}</h3><div class="cross-offer-product">${imageSmall(other)}<div><strong>${a('urun/'+other.id,esc(other.name))}</strong><p>${weight} g</p>${percent?`<div class="cross-offer-prices"><del>${money(unit)}</del><b>${money(discounted)}</b><span>%${percent} indirim</span></div><p class="cross-offer-explanation">${esc(main.name)} ile birlikte sepete eklerseniz bu ürüne %${percent} indirim uygulanır. Bir ana ürün için bir önerilen ürün indirimlidir. Sepette tek birlikte alım teklifi geçerlidir. Kuponla birleşmez; daha yüksek indirim uygulanır.</p>`:`<p>${money(unit)}</p>`}</div></div><button type="button" class="btn full" data-cross-add="${esc(other.id)}" data-cross-main="${esc(main.id)}" data-cross-weight="${weight}" data-cross-rule="${esc(rule?.id||'')}" ${stockFor(other,weight)<=0?'disabled':''}>${stockFor(other,weight)<=0?'Stokta yok':(percent?'Birlikte %'+percent+' indirimle ekle':'Sepete ekle')+' →'}</button></aside>`}
document.addEventListener('click',e=>{const button=e.target.closest('[data-cross-add]');if(!button)return;const main=product(button.dataset.crossMain),other=product(button.dataset.crossAdd),w=Number(button.dataset.crossWeight),mainWeight=selectedWeight;if(!main||!other)return;const hasMain=cart.some(x=>x.id===main.id&&!x.packageId);if(!hasMain&&stockFor(main,mainWeight)<=0){toast('Ana ürün şu anda stokta değil.');return}if(cart.filter(x=>x.id===other.id&&x.weight===w).reduce((n,x)=>n+x.qty,0)>=stockFor(other,w)){toast('Önerilen ürün için yeterli stok yok.');return}if(!hasMain){cart.push({id:main.id,weight:mainWeight,qty:1})}for(const item of cart)delete item.bundleRule;let item=cart.find(x=>x.id===other.id&&x.weight===w&&!x.packageId);if(item)item.qty=Math.min(99,item.qty+1);else{item={id:other.id,weight:w,qty:1};cart.push(item)}item.bundleRule=button.dataset.crossRule;saveCart();cartDrawer();});

function productUrlSlug(name){return String(name).toLocaleLowerCase('tr-TR').replace(/[ışğüöç]/g,c=>({'ı':'i','ş':'s','ğ':'g','ü':'u','ö':'o','ç':'c'}[c])).replace(/[^a-z0-9]+/g,'-').replace(/^-|-$/g,'')}

function heroSlides(){const h=config.hero||{};if(Array.isArray(h.slides)&&h.slides.length)return h.slides.slice(0,3).filter(x=>x.enabled!==false&&x.image);return h.enabled===false?[]:[{...h,image:h.image||'images/hero.webp'}]}
function heroSliderMarkup(){const h=config.hero||{},slides=heroSlides(),first=slides[0];if(!first)return '';return `<section class="hero hero-slider ${h.layout==='overlay'?'hero-overlay':''}" aria-label="Maya Peynir öne çıkanlar" aria-roledescription="slayt gösterisi"><div class="hero-copy"><div class="eyebrow">MAYA PEYNİR · KAHVALTIYA DAİR</div><h1>${esc(first.title||h.title||'Otel kahvaltısı, evinizin sofrasında.')}</h1><p>${esc(first.body||h.body||'Sofranıza eşlik edecek peynirleri keşfedin.')}</p><div class="actions">${a('peynirler','Peynirleri keşfet ↗','btn')}${a('hikayemiz','Hikâyemiz →','text-link')}</div></div><div class="hero-picture">${heroPicture({...h,...first})}<span class="image-caption">HER GÜNE BİR LEZZET.</span></div>${slides.length>1?`<div class="hero-slider-controls"><button type="button" data-hero-prev aria-label="Önceki slayt">←</button>${slides.map((x,i)=>`<button type="button" data-hero-index="${i}" aria-label="${i+1}. slaytı göster" aria-current="${i===0?'true':'false'}">${i+1}</button>`).join('')}<button type="button" data-hero-next aria-label="Sonraki slayt">→</button><button type="button" data-hero-pause aria-label="Otomatik geçişi durdur">Duraklat</button></div>`:''}</section>`}
function setupHeroSlider(){clearInterval(heroSlideTimer);const root=document.querySelector('.hero-slider'),slides=heroSlides();if(!root||slides.length<2)return;let index=0,paused=matchMedia('(prefers-reduced-motion: reduce)').matches,busy=false;const pause=root.querySelector('[data-hero-pause]');const update=()=>{pause.textContent=paused?'Oynat':'Duraklat';pause.setAttribute('aria-label',paused?'Otomatik geçişi başlat':'Otomatik geçişi durdur')};update();const move=async next=>{if(busy||!root.isConnected)return;next=(next+slides.length)%slides.length;if(next===index)return;busy=true;const slide=slides[next],image=new Image();image.src='image.php?src='+encodeURIComponent(innerWidth<=760?(slide.mobileImage||slide.image):slide.image)+'&w='+(innerWidth<=760?640:1440);try{await image.decode();if(!root.isConnected)return;root.classList.add('hero-changing');await new Promise(resolve=>setTimeout(resolve,180));if(!root.isConnected)return;index=next;root.querySelector('h1').textContent=slide.title||'';root.querySelector('.hero-copy > p').textContent=slide.body||'';root.querySelector('.hero-picture').innerHTML=heroPicture({...config.hero,...slide})+'<span class="image-caption">HER GÜNE BİR LEZZET.</span>';root.querySelectorAll('[data-hero-index]').forEach((b,i)=>b.setAttribute('aria-current',String(i===index)));requestAnimationFrame(()=>root.classList.remove('hero-changing'))}catch{}finally{busy=false}};root.querySelector('[data-hero-prev]').onclick=()=>move(index-1);root.querySelector('[data-hero-next]').onclick=()=>move(index+1);root.querySelectorAll('[data-hero-index]').forEach(b=>b.onclick=()=>move(Number(b.dataset.heroIndex)));pause.onclick=()=>{paused=!paused;update()};let touchX=null;root.addEventListener('touchstart',e=>touchX=e.touches[0].clientX,{passive:true});root.addEventListener('touchend',e=>{const dx=e.changedTouches[0].clientX-touchX;if(touchX!==null&&Math.abs(dx)>50)move(index+(dx<0?1:-1));touchX=null},{passive:true});heroSlideTimer=setInterval(()=>{if(!paused&&!document.hidden&&!root.matches(':hover')&&!root.contains(document.activeElement))move(index+1)},(config.hero?.interval||6)*1000)}

function contactChannels(){const c=config.contact||{};const normalized=value=>{let d=String(value||'').replace(/\D/g,'');if(d.length===11&&d.startsWith('0'))d='90'+d.slice(1);if(d.length===10)d='90'+d;return d};const phone=normalized(c.phone),whatsapp=normalized(c.whatsapp||c.phone);return {c,phone,whatsapp,email: /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(c.email||'')?c.email:'info@mayapeynir.com'}}
function supportIcon(type){const paths={chat:'<path d="M21 11.5a8.5 8.5 0 0 1-12.6 7.4L3 21l1.8-5.2A8.5 8.5 0 1 1 21 11.5Z"/><path d="M8 8c0 4 4 8 8 8l1-2-3-1-1 1-3-3 1-1-1-3-2 1Z"/>',phone:'<path d="m7 3 3 5-2 2c1.3 2.7 3.3 4.7 6 6l2-2 5 3c0 3-2 4-4 4C10 20 4 14 3 7c0-2 1-4 4-4Z"/>',mail:'<rect x="3" y="5" width="18" height="14" rx="1"/><path d="m3 6 9 7 9-7"/>'};return `<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" aria-hidden="true">${paths[type]}</svg>`}
function contactPage(){const {c,phone,whatsapp,email}=contactChannels();const card=(type,label,title,body,url)=>`<article class="support-channel ${type==='chat'?'support-whatsapp':''}">${supportIcon(type)}<div class="eyebrow">${label}</div><h2>${url?`<a href="${esc(url)}" ${type==='chat'?'target="_blank" rel="noopener noreferrer"':''}>${esc(title)}</a>`:esc(title)}</h2><p>${esc(body)}</p></article>`;return `<main id="main" class="container section support-page"><header class="support-heading"><div class="eyebrow">MÜŞTERİ DESTEĞİ</div><h1>İletişim</h1><p>${esc(c.intro||'Siparişiniz, ürünlerimiz veya önerileriniz için bize doğrudan ulaşabilirsiniz.')}</p></header><div class="support-channels">${card('chat','WHATSAPP',whatsapp?'WhatsApp’tan yazın':'Bize yazın','Sipariş numaranızı mesaja eklemeyi unutmayın.',whatsapp?'https://wa.me/'+whatsapp+'?text='+encodeURIComponent('Merhaba, siparişim / ürünleriniz hakkında bilgi almak istiyorum.'):'#contact-message')}${card('phone','TELEFON',c.phone||'İletişim formunu kullanabilirsiniz.','',phone?'tel:+'+phone:'')}${card('mail','E-POSTA',email,'','mailto:'+email)}</div><div class="support-columns"><section class="support-panel"><h2>Siparişinizle ilgili bir sorun mu var?</h2><ol><li>Sipariş numaranızı hazır tutun. Numara, sipariş onay e-postasında yer alır.</li><li>Sipariş numaranızla birlikte bize WhatsApp, telefon veya e-posta üzerinden ulaşabilirsiniz.</li></ol><div class="support-topic"><h3>Kargo takibi</h3><p>Siparişinizin tahmini gönderim ve teslimat aralığını ${a('teslimat','teslimat bilgileri')} bölümünden inceleyebilirsiniz. Kargo durumunu ${a('takip','Sipariş Takibi')} sayfasından takip edin.</p></div><div class="support-topic"><h3>Eksik veya hasarlı ürün</h3><p>${esc(c.damageInfo||'Sipariş numaranızı, ürünün ve paketin fotoğraflarını bizimle paylaşın. Talebinizi birlikte değerlendirelim.')}</p></div><div class="support-topic"><h3>Sık sorulan sorular</h3><p>${a('sss','Sipariş, kargo ve peynirler hakkında →')}</p></div>${c.business||c.address?`<div class="support-topic"><h3>${esc(c.business||'Adresimiz')}</h3><p style="white-space:pre-line">${esc(c.address||'')}</p></div>`:''}</section><section class="support-panel" id="contact-message"><h2>Bize yazın</h2><p>Mesajınızı bırakın; yanıtımızı formda belirttiğiniz e-posta adresine göndeririz.</p><form id="inquiry-form" class="support-form"><label class="sr-label">Ad<input name="name" placeholder="Ad soyad" required maxlength="160" autocomplete="name"></label><label class="sr-label">E-posta<input name="email" type="email" placeholder="E-posta" required autocomplete="email"></label><label class="sr-label">Sipariş numarası (varsa)<input name="order" placeholder="Sipariş no (varsa)" maxlength="100"></label><label class="sr-label">Mesaj<textarea name="body" placeholder="Mesajınız" required minlength="5" maxlength="10000" rows="6"></textarea></label><p class="help">${a('kvkk-aydinlatma','KVKK Aydınlatma Metni’ni inceleyin.')}</p><p data-inquiry-result role="status" aria-live="polite"></p><button class="btn full" type="submit">Mesajı gönder →</button></form></section></div></main>`}
function faqItems(){const c=config.contact||{};if(c.faqText?.trim())return c.faqText.split('\n').map(line=>{const [group,q,...answer]=line.split('|').map(x=>x.trim());return {group,q,answer:answer.join(' | ')}}).filter(x=>x.group&&x.q&&x.answer);return [{group:'Sipariş ve kargo',q:'Maya Peynir nedir?',answer:'Otellere ve profesyonel mutfaklara uzanan tedarik deneyimini ev müşterileriyle buluşturan peynir markasıdır.'},{group:'Sipariş ve kargo',q:'Siparişim ne zaman kargoya verilir?',answer:config.shipping?.enabled?'Tahmini kargoya veriliş ve teslimat aralıkları, güncel gönderim takvimine göre ürün ve ödeme sayfalarında gösterilir.':'Gönderim takvimi ve teslimat koşulları hakkında iletişim kanallarımızdan bilgi alabilirsiniz.'},{group:'Sipariş ve kargo',q:'Kargo ücreti ne kadar?',answer:`Kargo ücreti ${money(config.shippingFee)}. ${money(config.freeShipping)} ve üzerindeki siparişlerde kargo ücretsizdir.`},{group:'Sipariş ve kargo',q:'Ürünüm hasarlı ya da eksik gelirse ne yapmalıyım?',answer:c.damageInfo||'Sipariş numaranızı, ürünün ve paketin fotoğraflarını bizimle paylaşın. Talebinizi birlikte değerlendirelim.'},{group:'Sipariş ve kargo',q:'İade koşullarını nereden öğrenebilirim?',answer:'Ürüne ve teslimat durumuna uygun koşulları İptal ve İade Koşulları sayfasından inceleyebilirsiniz. Sorunuz varsa bizimle iletişime geçin.'},{group:'Peynirler',q:'İçerik ve alerjen bilgilerini nereden görebilirim?',answer:'Her ürünün içerik ve alerjen bilgilerini ilgili ürün sayfasındaki bilgi sekmelerinde inceleyebilirsiniz.'},{group:'Peynirler',q:'Peynirleri nasıl saklamalıyım?',answer:'Ürünün etiketindeki ve ürün sayfasındaki saklama koşullarını izleyin. Açıldıktan sonraki kullanım bilgilerini kontrol edin.'}]}
function faqPage(){const groups=new Map();for(const x of faqItems()){if(!groups.has(x.group))groups.set(x.group,[]);groups.get(x.group).push(x)}return `<main id="main" class="container section faq-page"><header class="support-heading"><div class="eyebrow">ALIŞVERİŞ REHBERİ</div><h1>Sık sorulan sorular</h1></header>${[...groups].map(([group,items])=>`<section class="faq-group"><h2>${esc(group)}</h2>${items.map(x=>`<details class="faq-item"><summary>${esc(x.q)}</summary><div class="faq-answer"><p>${esc(x.answer)}</p></div></details>`).join('')}</section>`).join('')}<nav class="faq-links">${a('takip','Sipariş takibi')}${a('teslimat','Teslimat ve paketleme')}${a('iptal-iade','İptal ve iade')}${a('iletisim','İletişim')}</nav></main>`}

function enableProductDrag(track){let drag=null,suppressClick=false;track.addEventListener('dragstart',e=>e.preventDefault());track.addEventListener('pointerdown',e=>{if(e.pointerType!=='mouse'||e.button!==0||e.target.closest('button,input,select,textarea'))return;drag={id:e.pointerId,x:e.clientX,left:track.scrollLeft,moved:false};suppressClick=false});track.addEventListener('pointermove',e=>{if(!drag||e.pointerId!==drag.id)return;const delta=e.clientX-drag.x;if(!drag.moved&&Math.abs(delta)<6)return;if(!drag.moved){drag.moved=true;track.setPointerCapture(e.pointerId);track.classList.add('is-dragging')}e.preventDefault();track.scrollLeft=drag.left-delta});const end=e=>{if(!drag||e.pointerId!==drag.id)return;suppressClick=drag.moved;drag=null;track.classList.remove('is-dragging');if(track.hasPointerCapture(e.pointerId))track.releasePointerCapture(e.pointerId);if(suppressClick)setTimeout(()=>suppressClick=false,0)};track.addEventListener('pointerup',end);track.addEventListener('pointercancel',end);track.addEventListener('lostpointercapture',()=>{drag=null;track.classList.remove('is-dragging')});track.addEventListener('click',e=>{if(suppressClick){e.preventDefault();e.stopImmediatePropagation();suppressClick=false}},true)}

function storeLogoMarkup(footer=false){const b=config.branding||{},path=b.logo??'images/maya-logo.png',business=config.contact?.business||'Maya Peynir';if(!path)return `<span class="store-brand-name">${esc(business)}</span>`;return `<img class="store-brand-logo ${footer?'footer-brand-logo':''}" src="assets/${esc(path)}" alt="${esc(business)}" width="${footer?125:Number(b.logoWidth)||138}" style="height:auto" decoding="async">`}

function navigationLabel(route,fallback){return config.navigationLabels?.[route]||(route==='seckiler'?config.collections?.title:'')||fallback}
function collectionPage(){
 const c=config.collections||{title:'Kahvaltı Seçkileri',eyebrow:'MAYA İLE KAHVALTI',body:'Peynirleri ve paketleri keşfedin.',sections:[]};
 const sections=(c.sections||[]).filter(x=>x.enabled!==false);
 return `<main id="main" class="container collections-page"><div class="crumb">${a('anasayfa','Ana sayfa')} / ${esc(c.title)}</div><header class="section collections-heading"><div class="eyebrow">${esc(c.eyebrow||'')}</div><h1>${esc(c.title)}</h1><p>${esc(c.body||'')}</p></header>${sections.map(x=>{
  const b=packageView(x),products=b?b.items:(x.products||[]).map(product).filter(Boolean);if(!products.length)return '';
  const layout=`collection-layout${x.imageSide==='right'?' image-right':''}${x.image?'':' no-image'}`;
  const visual=x.image?mediaImage(x.image,x.title,{width:960,widths:[480,640,960],sizes:'(max-width: 760px) 100vw, 50vw'}):'';
  const copy=`<div class="collection-copy"><h2>${b?a('paket/'+b.id,esc(x.title)):esc(x.title)}</h2><p>${esc(x.body||'')}</p></div>`;
  if(b)return `<section class="section collection-section collection-package"><div class="${layout}"><div class="collection-visual">${visual}</div><div class="collection-package-summary">${copy}<h3 class="package-list-title">Paketin içindekiler</h3>${packageMemberList(b.items)}${packagePriceMarkup(b)}<div class="actions">${a('paket/'+b.id,'Paketi incele →','btn secondary')}<button type="button" class="btn" data-package-add="${esc(b.id)}" ${b.available<1?'disabled':''}>${b.available<1?'Stokta yok':'Paketi sepete ekle'}</button></div></div></div></section>`;
  const columns=x.columns==='1'?'one-column':'two-columns',tail=x.columns!=='1'&&products.length>1&&products.length%2===1;
  return `<section class="section collection-section collection-showcase"><div class="${layout}"><div class="collection-visual">${visual}${copy}</div><div class="collection-products ${products.length===1?'one-column':columns}" data-count="${products.length}">${products.map((p,i)=>`<div class="collection-product ${tail&&i===products.length-1?'wide-last':''}">${card(p)}</div>`).join('')}</div></div></section>`;
 }).join('')}${!sections.length?'<section class="section"><p>Yeni seçkilerimizi burada paylaşacağız.</p>'+a('peynirler','Peynirleri keşfedin →','btn secondary')+'</section>':''}</main>`;
}
function packageMemberList(items){return `<ul class="package-member-list">${items.map(packageMemberCard).join('')}</ul>`}

function packageView(section){if(section.enabled===false||section.mode==='showcase'||!section.id)return null;if(section.bundle)return section.bundle;const lines=section.items?.length?section.items:(section.products||[]).map(id=>({id,weight:product(id)?.weights?.[0]||500,qty:1}));if(!lines.length)return null;let sales=0,regular=0;const items=[],needs={},stocks={};for(const x of lines){const p=product(x.id),w=Number(x.weight),qty=Number(x.qty);if(!p||qty<1||!p.weights.map(Number).includes(w))return null;const unit=Math.round(price(p,w)*100),regularUnit=Math.max(unit,Math.round((oldPrice(p,w)||price(p,w))*100));sales+=unit*qty;regular+=regularUnit*qty;const key=variant(p,w)?p.id+'|'+w:p.id;needs[key]=(needs[key]||0)+qty;stocks[key]=stockFor(p,w);items.push({id:p.id,name:p.name,weight:w,qty,unit,regularUnit,image:p.image,description:p.description,ingredients:p.ingredients,allergens:p.allergens,storage:p.storage})}let available=Infinity;for(const key in needs)available=Math.min(available,Math.floor(stocks[key]/needs[key]));const value=Math.max(0,Number(section.discountValue)||0),discount=Math.min(sales,section.discountType==='percent'?Math.round(sales*Math.min(100,value)/100):section.discountType==='fixed'?Math.round(value*100):0);return {id:section.id,slug:section.slug||section.id,name:section.title,description:section.body||'',image:section.image||'',gallery:section.gallery||[],items,salesTotal:sales,regularTotal:regular,packageDiscount:discount,total:sales-discount,available:Number.isFinite(available)?available:0}}
function findPackage(id){for(const s of config.collections?.sections||[]){if(s.id===id||s.slug===id)return packageView(s)}return null}
function packagePriceMarkup(b){return `<div class="package-prices"><p><span>Ürünlerin liste toplamı</span><del>${money(b.regularTotal/100)}</del></p><p><span>Güncel satış fiyatları toplamı</span><b>${money(b.salesTotal/100)}</b></p>${b.packageDiscount?`<p class="package-discount"><span>Paket indirimi</span><b>−${money(b.packageDiscount/100)}</b></p>`:''}<p class="package-final"><span>Paket toplamı</span><strong>${money(b.total/100)}</strong></p>${b.regularTotal>b.total?`<small>Toplam avantajınız: ${money((b.regularTotal-b.total)/100)}</small>`:''}</div>`}
function packageMemberCard(x){return `<li class="package-member-row">${a('urun/'+x.id,mediaImage(x.image,x.name,{width:320,widths:[320],sizes:'64px'}),'package-member-thumb')}<div class="package-member-copy"><h3>${a('urun/'+x.id,esc(x.name))}</h3><p>${Number(x.weight)} g</p></div><span class="package-member-quantity">× ${Number(x.qty)} adet</span></li>`}
function packageGallery(b){const paths=[...new Set([b.image,...(b.gallery||[])].filter(Boolean))];if(!paths.length)return '<div class="package-image-placeholder">Paket görseli henüz eklenmedi.</div>';return `<div class="package-gallery"><div class="package-main-visual">${mediaImage(paths[0],b.name,{eager:true,width:960})}</div>${paths.length>1?`<div class="gallery-thumbs">${paths.map((path,i)=>`<button type="button" data-package-thumb="${i}" data-package-id="${esc(b.id)}" aria-label="${i+1}. paket görseli" aria-pressed="${i===0}" class="${i===0?'selected':''}">${mediaImage(path,b.name+' · '+(i+1),{width:320})}</button>`).join('')}</div>`:''}</div>`}
function packageDetail(id){const b=findPackage(id);if(!b)return `<main id="main" class="container section"><h1>Paket bulunamadı.</h1>${a('seckiler','Paketleri keşfedin →','btn')}</main>`;const brief=(value,n=180)=>{const t=String(value||'').replace(/\s+/g,' ').trim();return t.length>n?t.slice(0,n).trim()+'…':t};return `<main id="main" class="container package-detail-page" data-package-root><div class="crumb">${a('anasayfa','Ana sayfa')} / ${a('seckiler',esc(navigationLabel('seckiler','Kahvaltı paketleri')))} / ${esc(b.name)}</div><div class="product-layout">${packageGallery(b)}<section class="package-detail-copy"><div class="eyebrow">MAYA KAHVALTI PAKETLERİ</div><h1>${esc(b.name)}</h1><div class="managed-body">${bodyParagraphs(b.description)}</div><h2 class="package-list-title">Paketin içindekiler</h2>${packageMemberList(b.items)}${packagePriceMarkup(b)}<label>Paket adedi<input type="number" data-package-qty min="1" max="99" value="1"></label><button class="btn full" type="button" data-package-add="${esc(b.id)}" ${b.available<1?'disabled':''}>${b.available<1?'Stokta yok':'Paketi sepete ekle →'}</button><p class="help">Paket fiyatı, burada belirtilen gramaj ve adetler için geçerlidir. Kupon ve otomatik indirimlerden daha avantajlı olan uygulanır.</p>${assuranceMarkup()}<h2 class="package-members-heading">Paketin içindekiler</h2><div class="package-members">${b.items.map(x=>`<article class="package-member-detail">${a('urun/'+x.id,mediaImage(x.image,x.name,{width:320}))}<div><h3>${a('urun/'+x.id,esc(x.name))}</h3><p>${Number(x.qty)} adet × ${Number(x.weight)} g</p><p>${esc(brief(x.description))}</p>${[['ingredients','İçerik'],['allergens','Alerjen'],['storage','Saklama']].map(([key,label])=>x[key]?`<p><b>${label}:</b> ${esc(brief(x[key],200))}</p>`:'').join('')}${a('urun/'+x.id,'Ürünün tüm bilgilerini incele →','text-link')}</div></article>`).join('')}</div></section></div></main>`}
async function addPackage(id,qty=1){const b=findPackage(id);if(!b||b.available<1){toast('Bu paket için yeterli stok yok.');return}qty=Math.max(1,Math.min(99,Math.floor(Number(qty)||1)));const next=cart.map(x=>({...x}));for(const x of b.items){const found=next.find(row=>row.id===x.id&&Number(row.weight)===Number(x.weight)&&row.packageId===b.id);if(found)found.qty+=x.qty*qty;else next.push({id:x.id,weight:Number(x.weight),qty:x.qty*qty,packageId:b.id,packageName:b.name})}if(next.length>30||next.some(x=>x.qty>99)){toast('Paket adedi sepet sınırını aşıyor. Daha az paket seçin.');return}let q=null;if(window.MAYA_SERVER)q=await serverApi('quote',{items:next,coupon:couponCode});cart=next;saveCart();if(q)checkoutQuote=q;cartDrawer();toast('Paketin ürünleri sepete eklendi.')}
document.addEventListener('click',async e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.packageAdd){if(b.disabled)return;b.disabled=true;try{await addPackage(b.dataset.packageAdd,b.closest('[data-package-root]')?.querySelector('[data-package-qty]')?.value||1)}catch(err){toast(err.message)}finally{if(b.isConnected)b.disabled=(findPackage(b.dataset.packageAdd)?.available||0)<1}}if(b.hasAttribute('data-package-thumb')){const p=findPackage(b.dataset.packageId),paths=p?[...new Set([p.image,...(p.gallery||[])].filter(Boolean))]:[],i=Number(b.dataset.packageThumb);if(paths[i]){const root=b.closest('.package-gallery');root.querySelector('.package-main-visual').innerHTML=mediaImage(paths[i],p.name,{eager:true,width:960});root.querySelectorAll('[data-package-thumb]').forEach((button,index)=>{button.setAttribute('aria-pressed',String(index===i));button.classList.toggle('selected',index===i)})}}});

function regularDeliveryCheckoutMarkup(){const offer=pendingRegularOffer();if(offer)return `<div class="regular-checkout"><b>${offer.percent?'Size özel %'+Number(offer.percent)+' indirim teklifi':'Özel sipariş hatırlatması'}</b><p class="help">İndirimlerden daha avantajlı olan toplamda gösterilir. Ödemeyi siz onaylarsınız.</p><button type="button" class="text-link" data-remove-regular-offer>Teklifi kaldır</button></div>`;const renewal=pendingRegularPlan();if(renewal)return '<div class="regular-checkout"><b>Düzenli gönderiminizi yeniliyorsunuz.</b><p class="help">Ödemeniz onaylanınca sonraki hatırlatma planlanır. Otomatik ödeme alınmaz.</p></div>';return `<div class="regular-checkout"><label class="checkbox"><input type="checkbox" id="regular-delivery-optin">Düzenli gönderim için hatırlatma istiyorum.</label><label id="regular-delivery-frequency" hidden>Sıklık<select id="regular-delivery-days" disabled>${[7,14,30,60,90].map(n=>`<option value="${n}" ${n===30?'selected':''}>${n} günde bir</option>`).join('')}</select></label><p class="help">İlk ödemeniz onaylanınca talebiniz açılır. Her yeni siparişi siz onaylayıp ödersiniz; otomatik ödeme alınmaz.</p></div>`}
document.addEventListener('change',e=>{if(e.target.id==='regular-delivery-optin'){const field=document.querySelector('#regular-delivery-frequency'),select=document.querySelector('#regular-delivery-days');field.hidden=!e.target.checked;select.disabled=!e.target.checked}});

function regularOfferPage(){return '<main id="main" class="container section regular-offer-page"><div id="regular-offer-content" role="status">Size özel sepet hazırlanıyor…</div></main>'}
async function loadRegularOffer(){const ticket=++regularOfferRequest,token=location.hash.startsWith('#teklif=')?location.hash.slice(8):pendingRegularOffer()?.token||'',target=document.querySelector('#regular-offer-content');if(!target)return;try{const r=await serverApi('regular-offer',{token});if(ticket!==regularOfferRequest||!target.isConnected)return;currentRegularOffer={...r,token};target.innerHTML=`<div class="eyebrow">MAYA’DAN SİZE</div><h1>${r.percent?'Size özel %'+Number(r.percent)+' indirim teklifi':'Peynirlerinizi yeniden keşfedin.'}</h1><p>Önceki seçiminizi güncel fiyatlarla hazırladık. Sepetinizi inceleyip ödemeyi kendiniz onaylayabilirsiniz.</p>${r.requiresLogin?'<p class="help">Bu teklif kendi müşteri hesabınızla giriş yaparak kullanılır.</p>':''}<div class="regular-offer-items">${r.items.map(x=>`<article>${mediaImage(x.image,x.name,{width:320})}<div><h2>${a('urun/'+x.id,esc(x.name))}</h2><p>${Number(x.qty)} adet × ${Number(x.weight)} g</p></div></article>`).join('')}</div><div class="regular-offer-total">${quotedTotalsMarkup(r.quote)}</div><p class="help">Teklifin son geçerlilik tarihi: ${new Date(r.expires*1000).toLocaleDateString('tr-TR',{timeZone:'Europe/Istanbul'})}. Diğer indirimlerden daha avantajlı olan uygulanır.</p><div class="actions"><button type="button" class="btn" data-use-regular-offer>Bu sepetle devam et →</button>${a('seckiler','Paketleri keşfet','btn secondary')}</div>`}catch(e){if(target.isConnected)target.innerHTML='<h1>Hatırlatma sepetiniz</h1><p>'+esc(e.message)+'</p>'+a('seckiler','Güncel paketleri keşfedin →','btn secondary')}}
document.addEventListener('click',async e=>{const use=e.target.closest('[data-use-regular-offer]');if(use&&currentRegularOffer&&!use.disabled){use.disabled=true;try{const next=cart.map(x=>({...x}));for(const x of currentRegularOffer.items){const found=next.find(row=>row.id===x.id&&Number(row.weight)===Number(x.weight)&&(row.packageId||'')===(x.packageId||''));if(found)found.qty+=Number(x.qty);else next.push({id:x.id,weight:Number(x.weight),qty:Number(x.qty),packageId:x.packageId||''})}const q=await serverApi('quote',{items:next,coupon:couponCode,regularOfferToken:currentRegularOffer.token});cart=next;saveCart();checkoutQuote=q;sessionStorage.setItem('maya-regular-offer',JSON.stringify({token:currentRegularOffer.token,percent:currentRegularOffer.percent}));sessionStorage.setItem('maya-regular-checkout',JSON.stringify({id:currentRegularOffer.planId,days:currentRegularOffer.days}));cartDrawer();toast('Size özel sepet hazır. Ödemeyi tamamlayarak sipariş verebilirsiniz.')}catch(err){toast(err.message)}finally{if(use.isConnected)use.disabled=false}}if(e.target.closest('[data-remove-regular-offer]')){try{sessionStorage.removeItem('maya-regular-offer');sessionStorage.removeItem('maya-regular-checkout')}catch{}render();toast('Özel teklif kaldırıldı.')}});
